1: import { describe, it, expect, beforeEach, afterEach } from '@jest/globals';
2: import * as fs from 'fs';
3: import * as path from 'path';
4: import * as os from 'os';
5: import { DatabaseManager } from '../../utils/database.js';
6: import { TestDatabaseHelper } from '../../test-helpers/database-helper.js';
7: 
8: describe('Concurrent Access Tests', () => {
9:   let tempDir: string;
10:   let tempDbPath: string;
11:   let dbManager: DatabaseManager;
12: 
13:   beforeEach(() => {
14:     tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'mcp-test-'));
15:     tempDbPath = path.join(tempDir, 'test.db');
16:     dbManager = TestDatabaseHelper.createTestDatabase();
17:   });
18: 
19:   afterEach(async () => {
20:     // Clean up all tracked databases
21:     await TestDatabaseHelper.cleanupAll();
22: 
23:     // Clean up temp directory
24:     try {
25:       fs.rmSync(tempDir, { recursive: true, force: true });
26:     } catch (_error) {
27:       console.warn('Error cleaning up temp directory:', _error);
28:     }
29: 
30:     // Clean up any WAL/SHM files
31:     TestDatabaseHelper.cleanupDbFiles(tempDbPath);
32:   });
33: 
34:   it('should handle concurrent session writes without corruption', async () => {
35:     const db = dbManager.getDatabase();
36:     const sessionId = 'test-session';
37: 
38:     // Create session
39:     db.prepare(
40:       `
41:       INSERT INTO sessions (id, name, description, branch, working_directory)
42:       VALUES (?, ?, ?, ?, ?)
43:     `
44:     ).run(sessionId, 'Test Session', 'Test', null, null);
45: 
46:     // Simulate concurrent writes to same session
47:     const promises = [];
48:     for (let i = 0; i < 10; i++) {
49:       promises.push(
50:         new Promise<void>(resolve => {
51:           setTimeout(() => {
52:             try {
53:               db.prepare(
54:                 `
55:               INSERT OR REPLACE INTO context_items (id, session_id, key, value, category, priority)
56:               VALUES (?, ?, ?, ?, ?, ?)
57:             `
58:               ).run(`item-${i}`, sessionId, `key-${i}`, `value-${i}`, 'test', 'normal');
59:               resolve();
60:             } catch (_error) {
61:               resolve(); // Still resolve to continue test
62:             }
63:           }, Math.random() * 10);
64:         })
65:       );
66:     }
67: 
68:     await Promise.all(promises);
69: 
70:     // Verify all items were written
71:     const items = db
72:       .prepare('SELECT COUNT(*) as count FROM context_items WHERE session_id = ?')
73:       .get(sessionId) as any;
74:     expect(items.count).toBe(10);
75:   });
76: 
77:   it('should handle concurrent updates to same key', async () => {
78:     const db = dbManager.getDatabase();
79:     const sessionId = 'test-session';
80:     const key = 'shared-key';
81: 
82:     // Create session
83:     db.prepare(
84:       `
85:       INSERT INTO sessions (id, name, description, branch, working_directory)
86:       VALUES (?, ?, ?, ?, ?)
87:     `
88:     ).run(sessionId, 'Test Session', 'Test', null, null);
89: 
90:     // Initial value
91:     db.prepare(
92:       `
93:       INSERT INTO context_items (id, session_id, key, value, category, priority)
94:       VALUES (?, ?, ?, ?, ?, ?)
95:     `
96:     ).run('initial', sessionId, key, 'initial-value', 'test', 'normal');
97: 
98:     // Concurrent updates
99:     const updates = [];
100:     for (let i = 0; i < 20; i++) {
101:       updates.push(
102:         new Promise<void>(resolve => {
103:           setTimeout(() => {
104:             try {
105:               db.prepare(
106:                 `
107:               UPDATE context_items 
108:               SET value = ?, updated_at = CURRENT_TIMESTAMP
109:               WHERE session_id = ? AND key = ?
110:             `
111:               ).run(`value-${i}`, sessionId, key);
112:               resolve();
113:             } catch (_error) {
114:               resolve();
115:             }
116:           }, Math.random() * 10);
117:         })
118:       );
119:     }
120: 
121:     await Promise.all(updates);
122: 
123:     // Should have exactly one item with the key
124:     const items = db
125:       .prepare('SELECT COUNT(*) as count FROM context_items WHERE session_id = ? AND key = ?')
126:       .get(sessionId, key) as any;
127:     expect(items.count).toBe(1);
128:   });
129: 
130:   it('should handle database locks gracefully', () => {
131:     const db = dbManager.getDatabase();
132: 
133:     // In WAL mode, readers don't block writers and vice versa
134:     // So we need to test a different scenario - two writers
135: 
136:     // Start a write transaction
137:     db.prepare('BEGIN IMMEDIATE').run();
138: 
139:     // Try to start another write transaction (should fail)
140:     let errorThrown = false;
141:     try {
142:       // This should fail because we already have a write transaction
143:       db.prepare('BEGIN IMMEDIATE').run();
144:     } catch (error: any) {
145:       errorThrown = true;
146:       // The exact error code might vary
147:       expect(error.message).toMatch(/database is locked|cannot start a transaction/i);
148:     }
149: 
150:     db.prepare('ROLLBACK').run();
151: 
152:     // If no error was thrown, it might be because SQLite is configured differently
153:     // In that case, just verify we can at least do transactions
154:     if (!errorThrown) {
155:       // Verify basic transaction works
156:       db.prepare('BEGIN').run();
157:       db.prepare('INSERT INTO sessions (id, name) VALUES (?, ?)').run('test', 'Test');
158:       db.prepare('COMMIT').run();
159: 
160:       const result = db.prepare('SELECT * FROM sessions WHERE id = ?').get('test') as any;
161:       expect(result.name).toBe('Test');
162:     }
163:   });
164: 
165:   it('should handle WAL mode concurrent reads during write', () => {
166:     const db = dbManager.getDatabase();
167: 
168:     // Verify WAL mode is enabled
169:     const journalMode = db.pragma('journal_mode') as any[];
170:     expect(journalMode[0].journal_mode).toBe('wal');
171: 
172:     // Create a session
173:     const sessionId = 'wal-test';
174:     db.prepare(
175:       `
176:       INSERT INTO sessions (id, name, description, branch, working_directory)
177:       VALUES (?, ?, ?, ?, ?)
178:     `
179:     ).run(sessionId, 'WAL Test', 'Test', null, null);
180: 
181:     // Start a write transaction
182:     const writeStmt = db.prepare('BEGIN IMMEDIATE');
183:     writeStmt.run();
184: 
185:     // Insert item in transaction
186:     db.prepare(
187:       `
188:       INSERT INTO context_items (id, session_id, key, value, category, priority)
189:       VALUES (?, ?, ?, ?, ?, ?)
190:     `
191:     ).run('item-1', sessionId, 'key-1', 'value-1', 'test', 'normal');
192: 
193:     // Read should work even with ongoing write transaction (WAL mode benefit)
194:     const readResult = db.prepare('SELECT COUNT(*) as count FROM sessions').get() as any;
195:     expect(readResult.count).toBeGreaterThan(0);
196: 
197:     // Commit the transaction
198:     db.prepare('COMMIT').run();
199:   });
200: });

