25:     // Create and initialize a real git repo for testing
26:     fs.mkdirSync(tempRepoPath, { recursive: true });
27:     git = simpleGit(tempRepoPath);
28:     await git.init(['--initial-branch=master']);
29:     await git.addConfig('user.name', 'Test User');
