43:   afterEach(async () => {
44:     // Clean up git processes first
45:     if (git) {
46:       try {
47:         // Clear any pending git operations
48:         git.removeAllListeners?.();
49:       } catch (error) {
50:         console.warn('Error cleaning up git:', error);
51:       }
