68:   describe('context_git_commit', () => {
69:     it('should automatically save context on commit', async () => {
70:       const sessionId = uuidv4();
71:       db.prepare('INSERT INTO sessions (id, name) VALUES (?, ?)').run(
72:         sessionId,
73:         'Git Test Session'
74:       );
75: 
76:       // Add context items
77:       const items = [
78:         { key: 'current_task', value: 'Implementing git integration', priority: 'high' },
79:         { key: 'decision', value: 'Use simple-git library', priority: 'normal' },
80:       ];
81: 
82:       items.forEach(item => {
83:         db.prepare(
84:           'INSERT INTO context_items (id, session_id, key, value, priority) VALUES (?, ?, ?, ?, ?)'
85:         ).run(uuidv4(), sessionId, item.key, item.value, item.priority);
86:       });
87: 
88:       // Make a change and commit
89:       fs.writeFileSync(path.join(tempRepoPath, 'test.txt'), 'test content');
90:       const git = simpleGit(tempRepoPath);
91:       await git.add('.');
92:       const commitResult = await git.commit('Test commit');
93: 
94:       // Simulate auto-save on commit
95:       const checkpointId = uuidv4();
96:       const gitInfo = await gitOps.getGitInfo();
97: 
98:       db.prepare(
99:         'INSERT INTO checkpoints (id, session_id, name, description, git_status, git_branch) VALUES (?, ?, ?, ?, ?, ?)'
100:       ).run(
101:         checkpointId,
102:         sessionId,
103:         `Git commit: ${commitResult.commit}`,
