114:         db.prepare(
115:           'INSERT INTO checkpoint_items (id, checkpoint_id, context_item_id) VALUES (?, ?, ?)'
116:         ).run(uuidv4(), checkpointId, item.id);
117:       });
118: 
119:       // Verify checkpoint was created
120:       const checkpoint = db
121:         .prepare('SELECT * FROM checkpoints WHERE id = ?')
122:         .get(checkpointId) as any;
123:       expect(checkpoint).toBeDefined();
124:       expect(checkpoint.name).toContain('Git commit:');
