128:     it('should capture git status in checkpoint', async () => {
129:       const sessionId = uuidv4();
130:       db.prepare('INSERT INTO sessions (id, name) VALUES (?, ?)').run(sessionId, 'Status Test');
131: 
132:       // Create some changes
133:       fs.writeFileSync(path.join(tempRepoPath, 'modified.txt'), 'original');
134:       const git = simpleGit(tempRepoPath);
135:       await git.add('.');
136:       await git.commit('Add file');
137: 
138:       // Modify file
139:       fs.writeFileSync(path.join(tempRepoPath, 'modified.txt'), 'changed');
140: 
141:       // Create new file
142:       fs.writeFileSync(path.join(tempRepoPath, 'new.txt'), 'new content');
143: 
144:       // Stage one file
145:       await git.add('modified.txt');
146: 
147:       // Get git info
148:       const gitInfo = await gitOps.getGitInfo();
149: 
150:       // Create checkpoint with git status
151:       const checkpointId = uuidv4();
152:       db.prepare(
153:         'INSERT INTO checkpoints (id, session_id, name, git_status, git_branch) VALUES (?, ?, ?, ?, ?)'
154:       ).run(checkpointId, sessionId, 'Status Checkpoint', gitInfo.status, gitInfo.branch);
155: 
156:       const checkpoint = db
157:         .prepare('SELECT * FROM checkpoints WHERE id = ?')
158:         .get(checkpointId) as any;
159: 
160:       expect(checkpoint.git_status).toContain('modified.txt');
161:       // Parse the status to check properly
162:       const status = JSON.parse(checkpoint.git_status);
163:       expect(status.not_added).toContain('new.txt');
164:       expect(checkpoint.git_branch).toBe('master'); // Default branch name
165:     });
166: 
167:     it('should handle commits with message containing context summary', async () => {
168:       const sessionId = uuidv4();
169:       db.prepare('INSERT INTO sessions (id, name) VALUES (?, ?)').run(
170:         sessionId,
171:         'Commit Message Test'
172:       );
173: 
174:       // Add context items that should be in commit message
175:       const tasks = [
176:         { key: 'task1', value: 'Fixed authentication bug' },
177:         { key: 'task2', value: 'Added user validation' },
178:       ];
179: 
180:       tasks.forEach(task => {
181:         db.prepare(
182:           'INSERT INTO context_items (id, session_id, key, value, category) VALUES (?, ?, ?, ?, ?)'
183:         ).run(uuidv4(), sessionId, task.key, task.value, 'task');
