185: 
186:       // Generate commit message with context
187:       const completedTasks = db
188:         .prepare('SELECT value FROM context_items WHERE session_id = ? AND category = ?')
189:         .all(sessionId, 'task') as any[];
190: 
191:       const commitMessage = [
192:         'Feature: User authentication improvements',
193:         '',
194:         'Tasks completed:',
195:         ...completedTasks.map((t: any) => `- ${t.value}`),
196:         '',
197:         '[Context saved by MCP Memory Keeper]',
198:       ].join('\n');
199: 
200:       // Make change and commit
201:       fs.writeFileSync(path.join(tempRepoPath, 'auth.js'), 'auth code');
202:       const git = simpleGit(tempRepoPath);
203:       await git.add('.');
204:       const commitResult = await git.commit(commitMessage);
205: 
206:       expect(commitResult.commit).toBeTruthy();
207: 
208:       // Verify commit message
209:       const log = await git.log(['-1']);
210:       expect(log.latest).toBeDefined();
211:       expect(log.latest?.message || log.latest?.hash).toBeDefined();
212:       // The actual message should be in the latest entry
213:     });
214: 
215:     it('should link commits to sessions', async () => {
216:       const sessionId = uuidv4();
217:       db.prepare('INSERT INTO sessions (id, name) VALUES (?, ?)').run(
218:         sessionId,
219:         'Linked Commit Test'
220:       );
221: 
222:       // Make multiple commits
223:       const git = simpleGit(tempRepoPath);
224:       const commits: string[] = [];
225: 
226:       for (let i = 0; i < 3; i++) {
227:         fs.writeFileSync(path.join(tempRepoPath, `file${i}.txt`), `content ${i}`);
228:         await git.add('.');
229:         const result = await git.commit(`Commit ${i}`);
230:         commits.push(result.commit);
