232:         // Link commit to session - store commit hash in description
233:         const checkpointId = uuidv4();
234:         db.prepare(
235:           'INSERT INTO checkpoints (id, session_id, name, description) VALUES (?, ?, ?, ?)'
236:         ).run(checkpointId, sessionId, `Commit ${i}`, `Commit hash: ${result.commit}`);
237:       }
238: 
239:       // Query commits for session - using description field instead of metadata
240:       const sessionCommits = db
241:         .prepare(
242:           `SELECT * FROM checkpoints 
243:          WHERE session_id = ? 
244:          AND description LIKE 'Commit hash:%'
245:          ORDER BY created_at`
246:         )
247:         .all(sessionId) as any[];
248: 
249:       expect(sessionCommits).toHaveLength(3);
250:       sessionCommits.forEach((checkpoint: any, i: number) => {
251:         // Extract commit hash from description
252:         const match = checkpoint.description.match(/Commit hash: (.+)/);
253:         expect(match).toBeTruthy();
254:         expect(match[1]).toBe(commits[i]);
255:       });
256:     });
257:   });
258: 
259:   describe('Git error handling', () => {
260:     it('should handle non-git directories gracefully', async () => {
