281: });

src/__tests__/integration/tool-profiles-.numbered_source:
1: import { describe, it, expect } from '@jest/globals';
2: import * as fs from 'fs';
3: import * as path from 'path';
4: import {
5:   ALL_TOOL_NAMES,
6:   ALL_TOOL_NAMES_SET,
7:   resolveActiveProfile,
8: } from '../../utils/tool-profiles';
9: 
10: /**
11:  * Drift-detection: extract tool names from the ListToolsRequestSchema handler
12:  * in src/index.ts to verify ALL_TOOL_NAMES stays in sync with actual tool definitions.
13:  */
14: function extractToolNamesFromIndexTs(): string[] {
15:   const indexPath = path.join(__dirname, '..', '..', 'index.ts');
16:   const src = fs.readFileSync(indexPath, 'utf-8');
17: 
18:   // Find the allTools array: starts after "const allTools" and ends at the matching "];"
19:   // We look for tool name strings inside the ListToolsRequestSchema handler
20:   const toolNameRegex = /^\s+name:\s+'(context_[a-z_]+)'/gm;
21:   const names: string[] = [];
22:   let match;
23: 
24:   // Only capture tool names outside of block comments (skip commented-out tools)
25:   // Split by block comment boundaries and only scan non-comment sections
26:   const sections = src.split(/\/\*[\s\S]*?\*\//);
27:   for (const section of sections) {
28:     toolNameRegex.lastIndex = 0;
29:     while ((match = toolNameRegex.exec(section)) !== null) {
30:       names.push(match[1]);
31:     }
32:   }
33: 
34:   return names;
35: }
36: 
37: describe('Tool Profile Integration Tests', () => {
38:   const originalEnv = process.env.TOOL_PROFILE;
39: 
40:   afterEach(() => {
41:     if (originalEnv !== undefined) {
42:       process.env.TOOL_PROFILE = originalEnv;
43:     } else {
44:       delete process.env.TOOL_PROFILE;
45:     }
46:   });
47: 
48:   describe('Drift detection: ALL_TOOL_NAMES vs index.ts', () => {
49:     it('ALL_TOOL_NAMES should match active tools defined in index.ts', () => {
50:       const indexToolNames = extractToolNamesFromIndexTs();
51:       const allToolNamesArray = [...ALL_TOOL_NAMES];
52: 
53:       // Same count
54:       expect(allToolNamesArray.length).toBe(indexToolNames.length);
55: 
56:       // Same set of names
57:       expect(new Set(allToolNamesArray)).toEqual(new Set(indexToolNames));
58:     });
59: 
60:     it('should not include commented-out tools', () => {
61:       // context_share and context_get_shared are commented out in index.ts
62:       expect(ALL_TOOL_NAMES_SET.has('context_share')).toBe(false);
63:       expect(ALL_TOOL_NAMES_SET.has('context_get_shared')).toBe(false);
64:     });
65:   });
66: 
67:   describe('Profile filtering behavior', () => {
68:     it('minimal profile should include core tools and exclude advanced tools', () => {
69:       process.env.TOOL_PROFILE = 'minimal';
70:       const profile = resolveActiveProfile('/nonexistent/config.json');
71: 
72:       // Core tools present
73:       expect(profile.tools.has('context_save')).toBe(true);
74:       expect(profile.tools.has('context_get')).toBe(true);
75:       expect(profile.tools.has('context_search')).toBe(true);
76:       expect(profile.tools.has('context_checkpoint')).toBe(true);
77: 
78:       // Advanced tools absent
79:       expect(profile.tools.has('context_analyze')).toBe(false);
80:       expect(profile.tools.has('context_visualize')).toBe(false);
81:       expect(profile.tools.has('context_delegate')).toBe(false);
82:       expect(profile.tools.has('context_semantic_search')).toBe(false);
83:     });
84: 
85:     it('default (no env var) should expose all tools with backwards-compatible behavior', () => {
86:       delete process.env.TOOL_PROFILE;
87:       const profile = resolveActiveProfile('/nonexistent/config.json');
88:       expect(profile.tools.size).toBe(ALL_TOOL_NAMES.length);
89:       expect(profile.profileName).toBe('full');
90:       expect(profile.source).toBe('default');
91:       expect(profile.warnings).toHaveLength(0);
92:     });
93:   });
94: 
95:   describe('CallTool guard behavior', () => {
96:     it('disabled tool should be in ALL_TOOL_NAMES_SET but not in profile tools', () => {
97:       process.env.TOOL_PROFILE = 'minimal';
98:       const profile = resolveActiveProfile('/nonexistent/config.json');
99: 
100:       const disabledTool = 'context_analyze';
101: 
102:       // The guard logic: known tool that is not enabled
103:       const isKnown = ALL_TOOL_NAMES_SET.has(disabledTool);
104:       const isEnabled = profile.tools.has(disabledTool);
105: 
106:       expect(isKnown).toBe(true);
107:       expect(isEnabled).toBe(false);
108:       // In index.ts: isKnown && !isEnabled → return isError: true
109:     });
110: 
111:     it('unknown tool should not be in ALL_TOOL_NAMES_SET (falls through to default switch)', () => {
112:       const unknownTool = 'non_existent_tool';
113:       expect(ALL_TOOL_NAMES_SET.has(unknownTool)).toBe(false);
114:       // In index.ts: !isKnown → falls through to default: throw new Error()
115:     });
116: 
117:     it('enabled tool should pass both checks', () => {
118:       process.env.TOOL_PROFILE = 'minimal';
119:       const profile = resolveActiveProfile('/nonexistent/config.json');
120: 
121:       const enabledTool = 'context_save';
122:       const isKnown = ALL_TOOL_NAMES_SET.has(enabledTool);
123:       const isEnabled = profile.tools.has(enabledTool);
124: 
125:       expect(isKnown).toBe(true);
126:       expect(isEnabled).toBe(true);
127:       // In index.ts: isKnown && isEnabled → guard does not fire, proceeds to switch
128:     });
129:   });
130: 
131:   describe('TOOL_PROFILE_CONFIG support', () => {
132:     it('resolveActiveProfile accepts custom config path (used by TOOL_PROFILE_CONFIG)', () => {
133:       // This tests the mechanism that index.ts uses:
134:       // resolveActiveProfile(process.env.TOOL_PROFILE_CONFIG)
135:       const result = resolveActiveProfile('/nonexistent/custom/path/config.json');
