128: // Pagination validation utility
129: interface PaginationParams {
130:   limit?: any;
131:   offset?: any;
132: }
133: 
134: interface ValidatedPagination {
135:   limit: number;
136:   offset: number;
137:   errors: string[];
138: }
139: 
140: function validatePaginationParams(params: PaginationParams): ValidatedPagination {
141:   const errors: string[] = [];
142:   let limit = 25; // default
143:   let offset = 0; // default
144: 
145:   // Validate limit
146:   if (params.limit !== undefined && params.limit !== null) {
147:     const rawLimit = params.limit;
148:     if (!Number.isInteger(rawLimit) || rawLimit <= 0) {
149:       errors.push(`Invalid limit: expected positive integer, got ${typeof rawLimit} '${rawLimit}'`);
150:       debugLog(`Pagination validation: Invalid limit ${rawLimit}, using default ${limit}`);
151:     } else {
152:       limit = Math.min(Math.max(1, rawLimit), 100); // clamp between 1-100
153:       if (limit !== rawLimit) {
154:         debugLog(`Pagination validation: Clamped limit from ${rawLimit} to ${limit}`);
155:       }
156:     }
157:   }
158: 
159:   // Validate offset
160:   if (params.offset !== undefined && params.offset !== null) {
161:     const rawOffset = params.offset;
162:     if (!Number.isInteger(rawOffset) || rawOffset < 0) {
163:       errors.push(
164:         `Invalid offset: expected non-negative integer, got ${typeof rawOffset} '${rawOffset}'`
165:       );
166:       debugLog(`Pagination validation: Invalid offset ${rawOffset}, using default ${offset}`);
167:     } else {
168:       offset = rawOffset;
169:     }
170:   }
171: 
172:   return { limit, offset, errors };
173: }
