204:   totalSize: number;
205:   estimatedTokens: number;
206:   averageSize: number;
207: } {
208:   let totalSize = 0;
209: 
210:   for (const item of items) {
211:     const itemSize = item.size || calculateSize(item.value);
212:     totalSize += itemSize;
213:   }
214: 
215:   // Convert to JSON string to get actual response size
216:   const jsonString = JSON.stringify(items);
217:   const estimatedTokens = estimateTokens(jsonString);
218:   const averageSize = items.length > 0 ? Math.round(totalSize / items.length) : 0;
219: 
220:   return { totalSize, estimatedTokens, averageSize };
221: }
