226: // Helper to parse relative time strings
227: function parseRelativeTime(relativeTime: string): string | null {
228:   const now = new Date();
229:   const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
230: 
231:   if (relativeTime === 'today') {
232:     return today.toISOString();
233:   } else if (relativeTime === 'yesterday') {
234:     return new Date(today.getTime() - 24 * 60 * 60 * 1000).toISOString();
235:   } else if (relativeTime.match(/^(\d+) hours? ago$/)) {
236:     const hours = parseInt(relativeTime.match(/^(\d+)/)![1]);
237:     return new Date(now.getTime() - hours * 60 * 60 * 1000).toISOString();
238:   } else if (relativeTime.match(/^(\d+) days? ago$/)) {
239:     const days = parseInt(relativeTime.match(/^(\d+)/)![1]);
240:     return new Date(now.getTime() - days * 24 * 60 * 60 * 1000).toISOString();
241:   } else if (relativeTime === 'this week') {
242:     const startOfWeek = new Date(today);
243:     startOfWeek.setDate(today.getDate() - today.getDay());
244:     return startOfWeek.toISOString();
245:   } else if (relativeTime === 'last week') {
246:     const startOfLastWeek = new Date(today);
247:     startOfLastWeek.setDate(today.getDate() - today.getDay() - 7);
248:     return startOfLastWeek.toISOString();
249:   }
250: 
251:   return null;
252: }
