269: // Helper to get git status for a session
270: async function getGitStatus(sessionId?: string): Promise<{ status: string; branch: string }> {
271:   // Get the current session's working directory
272:   const session = sessionId
273:     ? repositories.sessions.getById(sessionId)
274:     : repositories.sessions.getById(currentSessionId || '');
275: 
276:   if (!session || !session.working_directory) {
277:     return { status: 'No project directory set', branch: 'none' };
278:   }
279: 
280:   try {
281:     const git = simpleGit(session.working_directory);
282:     const status = await git.status();
283:     const branch = await git.branch();
284:     return {
285:       status: JSON.stringify({
286:         modified: status.modified,
287:         created: status.created,
288:         deleted: status.deleted,
289:         staged: status.staged,
290:         ahead: status.ahead,
291:         behind: status.behind,
292:       }),
293:       branch: branch.current,
294:     };
295:   } catch (_e) {
296:     return { status: 'No git repository', branch: 'none' };
297:   }
298: }
