300: // Helper to create summary
301: function createSummary(
302:   items: any[],
303:   options: { categories?: string[]; maxLength?: number }
304: ): string {
305:   const { categories, maxLength = 1000 } = options;
306: 
307:   let filteredItems = items;
308:   if (categories && categories.length > 0) {
309:     filteredItems = items.filter(item => categories.includes(item.category));
310:   }
311: 
312:   // Group by category
313:   const grouped: Record<string, any[]> = filteredItems.reduce(
314:     (acc, item) => {
315:       const cat = item.category || 'uncategorized';
316:       if (!acc[cat]) acc[cat] = [];
317:       acc[cat].push(item);
318:       return acc;
319:     },
320:     {} as Record<string, any[]>
321:   );
322: 
323:   // Build summary
324:   let summary = '# Context Summary\n\n';
325: 
326:   // High priority items first
327:   const highPriorityItems = filteredItems.filter(item => item.priority === 'high');
328:   if (highPriorityItems.length > 0) {
329:     summary += '## High Priority Items\n';
330:     highPriorityItems.forEach(item => {
331:       summary += `- **${item.key}**: ${item.value.substring(0, 200)}${item.value.length > 200 ? '...' : ''}\n`;
332:     });
333:     summary += '\n';
334:   }
335: 
336:   // Then by category
337:   Object.entries(grouped).forEach(([category, categoryItems]) => {
338:     if (category !== 'uncategorized') {
339:       summary += `## ${category.charAt(0).toUpperCase() + category.slice(1)}\n`;
340:       categoryItems.forEach((item: any) => {
341:         if (item.priority !== 'high') {
342:           // Already shown above
343:           summary += `- ${item.key}: ${item.value.substring(0, 100)}${item.value.length > 100 ? '...' : ''}\n`;
344:         }
345:       });
346:       summary += '\n';
347:     }
348:   });
349: 
350:   // Truncate if needed
351:   if (summary.length > maxLength) {
352:     summary = summary.substring(0, maxLength - 3) + '...';
353:   }
354: 
355:   return summary;
356: }
