699:         limit: rawLimit,
700:         offset: rawOffset,
701:         createdAfter,
702:         createdBefore,
703:         keyPattern,
704:         priorities,
705:       } = args;
706:       const targetSessionId = specificSessionId || currentSessionId || ensureSession();
707: 
708:       // Dynamically calculate safe default limit based on actual data
709:       const defaultLimit = calculateDynamicDefaultLimit(targetSessionId, includeMetadata, db);
710:       const paginationValidation = validatePaginationParams({
711:         limit: rawLimit !== undefined ? rawLimit : defaultLimit,
712:         offset: rawOffset,
713:       });
714:       const { limit, offset, errors: paginationErrors } = paginationValidation;
715: 
716:       // Log pagination validation errors for debugging
717:       if (paginationErrors.length > 0) {
718:         debugLog('context_get pagination validation errors:', paginationErrors);
719:       }
720: 
721:       // Always use enhanced query to ensure consistent pagination
722:       // This prevents token limit issues when querying large datasets
723:       // Removed the conditional check since we always want to use this path
724:       {
725:         const result = repositories.contexts.queryEnhanced({
726:           sessionId: targetSessionId,
727:           key,
728:           category,
729:           channel,
730:           channels,
731:           sort,
732:           limit,
733:           offset,
734:           createdAfter,
735:           createdBefore,
736:           keyPattern,
737:           priorities,
738:           includeMetadata,
739:         });
740: 
741:         if (result.items.length === 0) {
742:           return {
743:             content: [
744:               {
745:                 type: 'text',
746:                 text: 'No matching context found',
747:               },
748:             ],
749:           };
750:         }
751: 
752:         // Use dynamic token limit checking
753:         const tokenConfig = getTokenConfig();
754:         const { exceedsLimit, estimatedTokens, safeItemCount } = checkTokenLimit(
755:           result.items,
756:           includeMetadata,
757:           tokenConfig
758:         );
759: 
760:         let actualItems = result.items;
761:         let wasTruncated = false;
762:         let truncatedCount = 0;
763: 
764:         if (exceedsLimit) {
765:           // Truncate to safe item count
766:           if (safeItemCount < result.items.length) {
767:             actualItems = result.items.slice(0, safeItemCount);
768:             wasTruncated = true;
769:             truncatedCount = result.items.length - safeItemCount;
770: 
771:             debugLog(
772:               `Token limit enforcement: Truncating from ${result.items.length} to ${safeItemCount} items`
773:             );
774:           }
775:         }
776: 
777:         // Calculate response metrics for the actual items being returned
778:         const metrics = calculateResponseMetrics(actualItems);
779: 
780:         // Calculate pagination metadata
781:         // Use the validated limit and offset from paginationValidation
782:         const effectiveLimit = limit; // Already validated and defaulted
783:         const effectiveOffset = offset; // Already validated and defaulted
784:         const currentPage =
785:           effectiveLimit > 0 ? Math.floor(effectiveOffset / effectiveLimit) + 1 : 1;
786:         const totalPages = effectiveLimit > 0 ? Math.ceil(result.totalCount / effectiveLimit) : 1;
787: 
788:         // Update pagination to account for truncation
789:         const hasNextPage = wasTruncated || currentPage < totalPages;
790:         const hasPreviousPage = currentPage > 1;
791: 
792:         // Calculate next offset accounting for truncation
793:         const nextOffset = hasNextPage
794:           ? wasTruncated
795:             ? effectiveOffset + actualItems.length
796:             : effectiveOffset + effectiveLimit
797:           : null;
798: 
799:         // Track whether defaults were applied
800:         const defaultsApplied = {
801:           limit: rawLimit === undefined,
802:           sort: sort === undefined,
803:         };
804: 
805:         // Enhanced response format
806:         if (includeMetadata) {
807:           const itemsWithMetadata = actualItems.map(item => ({
808:             key: item.key,
809:             value: item.value,
810:             category: item.category,
811:             priority: item.priority,
812:             channel: item.channel,
813:             metadata: item.metadata ? JSON.parse(item.metadata) : null,
814:             size: item.size || calculateSize(item.value),
815:             created_at: item.created_at,
816:             updated_at: item.updated_at,
817:           }));
818: 
819:           const response: any = {
820:             items: itemsWithMetadata,
821:             pagination: {
822:               total: result.totalCount,
823:               returned: actualItems.length,
824:               offset: effectiveOffset,
825:               hasMore: hasNextPage,
826:               nextOffset: nextOffset,
827:               // Extended pagination metadata
828:               totalCount: result.totalCount,
829:               page: currentPage,
830:               pageSize: effectiveLimit,
831:               totalPages: totalPages,
832:               hasNextPage: hasNextPage,
833:               hasPreviousPage: hasPreviousPage,
834:               previousOffset: hasPreviousPage
835:                 ? Math.max(0, effectiveOffset - effectiveLimit)
836:                 : null,
837:               // Size information
838:               totalSize: metrics.totalSize,
839:               averageSize: metrics.averageSize,
840:               // Defaults applied
841:               defaultsApplied: defaultsApplied,
842:               // Truncation information
843:               truncated: wasTruncated,
844:               truncatedCount: truncatedCount,
845:             },
846:           };
847: 
848:           // Add warning if truncation occurred
849:           if (wasTruncated) {
850:             response.pagination.warning = `Response truncated to prevent token overflow (estimated ${estimatedTokens} tokens). ${truncatedCount} items omitted. Use pagination with offset=${nextOffset} to retrieve remaining items.`;
851:             response.pagination.tokenInfo = {
852:               estimatedTokens,
853:               maxAllowed: tokenConfig.mcpMaxTokens,
854:               safeLimit: Math.floor(tokenConfig.mcpMaxTokens * tokenConfig.safetyBuffer),
855:             };
856:           } else if (estimatedTokens > tokenConfig.mcpMaxTokens * TOKEN_WARNING_THRESHOLD) {
857:             response.pagination.warning =
858:               'Large result set approaching token limits. Consider using smaller limit or more specific filters.';
859:           }
860: 
861:           return {
862:             content: [
863:               {
864:                 type: 'text',
865:                 text: JSON.stringify(response, null, 2),
866:               },
867:             ],
868:           };
869:         }
870: 
871:         // Return enhanced format for all queries to support pagination
872:         const response: any = {
873:           items: actualItems,
874:           pagination: {
875:             total: result.totalCount,
876:             returned: actualItems.length,
877:             offset: effectiveOffset,
878:             hasMore: hasNextPage,
879:             nextOffset: nextOffset,
880:             // Truncation information
881:             truncated: wasTruncated,
882:             truncatedCount: truncatedCount,
883:           },
884:         };
885: 
886:         // Add warning if truncation occurred
