2651:       const { olderThan, preserveCategories = [], targetSize: _targetSize, sessionId } = args;
2652:       const targetSessionId = sessionId || ensureSession();
2653: 
2654:       try {
2655:         // Build query for items to compress
2656:         let query = 'SELECT * FROM context_items WHERE session_id = ?';
2657:         const params: any[] = [targetSessionId];
2658: 
2659:         if (olderThan) {
2660:           query += ' AND created_at < ?';
2661:           params.push(olderThan);
2662:         }
2663: 
2664:         if (preserveCategories.length > 0) {
2665:           query += ` AND category NOT IN (${preserveCategories.map(() => '?').join(',')})`;
2666:           params.push(...preserveCategories);
2667:         }
2668: 
2669:         const itemsToCompress = db.prepare(query).all(...params) as any[];
2670: 
2671:         if (itemsToCompress.length === 0) {
2672:           return {
2673:             content: [
2674:               {
2675:                 type: 'text',
2676:                 text: 'No items found to compress with given criteria.',
2677:               },
2678:             ],
2679:           };
2680:         }
2681: 
2682:         // Group items by category for compression
2683:         const categoryGroups: Record<string, any[]> = {};
2684:         for (const item of itemsToCompress) {
2685:           const category = item.category || 'uncategorized';
2686:           if (!categoryGroups[category]) {
2687:             categoryGroups[category] = [];
2688:           }
2689:           categoryGroups[category].push(item);
2690:         }
2691: 
2692:         // Compress each category group
2693:         const compressed: any[] = [];
2694:         for (const [category, items] of Object.entries(categoryGroups)) {
2695:           const summary = {
2696:             category,
2697:             count: items.length,
2698:             priorities: { high: 0, normal: 0, low: 0 },
2699:             keys: items.map((i: any) => i.key),
2700:             samples: items
2701:               .slice(0, 3)
2702:               .map((i: any) => ({ key: i.key, value: i.value.substring(0, 100) })),
2703:           };
2704: 
2705:           for (const item of items) {
2706:             const priority = (item.priority || 'normal') as 'high' | 'normal' | 'low';
2707:             summary.priorities[priority]++;
2708:           }
2709: 
2710:           compressed.push(summary);
2711:         }
2712: 
2713:         // Calculate compression
2714:         const originalSize = JSON.stringify(itemsToCompress).length;
2715:         const compressedData = JSON.stringify(compressed);
2716:         const compressedSize = compressedData.length;
2717:         const compressionRatio = 1 - compressedSize / originalSize;
2718: 
2719:         // Store compressed data
2720:         const compressedId = uuidv4();
2721:         const dateRange = itemsToCompress.reduce(
2722:           (acc, item) => {
2723:             const date = new Date(item.created_at);
2724:             if (!acc.start || date < acc.start) acc.start = date;
2725:             if (!acc.end || date > acc.end) acc.end = date;
2726:             return acc;
2727:           },
2728:           { start: null as Date | null, end: null as Date | null }
2729:         );
2730: 
2731:         db.prepare(
2732:           `
2733:           INSERT INTO compressed_context (id, session_id, original_count, compressed_data, compression_ratio, date_range_start, date_range_end)
2734:           VALUES (?, ?, ?, ?, ?, ?, ?)
2735:         `
2736:         ).run(
2737:           compressedId,
2738:           targetSessionId,
2739:           itemsToCompress.length,
2740:           compressedData,
2741:           compressionRatio,
2742:           dateRange.start?.toISOString(),
2743:           dateRange.end?.toISOString()
2744:         );
2745: 
2746:         // Delete original items
2747:         const deleteStmt = db.prepare('DELETE FROM context_items WHERE id = ?');
2748:         for (const item of itemsToCompress) {
2749:           deleteStmt.run(item.id);
2750:         }
2751: 
2752:         return {
2753:           content: [
2754:             {
2755:               type: 'text',
2756:               text: `Compression completed!
2757: Items compressed: ${itemsToCompress.length}
2758: Original size: ${(originalSize / 1024).toFixed(2)} KB
2759: Compressed size: ${(compressedSize / 1024).toFixed(2)} KB
2760: Compression ratio: ${(compressionRatio * 100).toFixed(1)}%
2761: Date range: ${dateRange.start?.toISOString().substring(0, 10)} to ${dateRange.end?.toISOString().substring(0, 10)}
2762: 
2763: Categories compressed:
2764: ${Object.entries(categoryGroups)
2765:   .map(([cat, items]) => `- ${cat}: ${items.length} items`)
2766:   .join('\n')}
2767: 
2768: Compressed data ID: ${compressedId.substring(0, 8)}`,
2769:             },
2770:           ],
2771:         };
2772:       } catch (error: any) {
2773:         return {
2774:           content: [
2775:             {
2776:               type: 'text',
2777:               text: `Compression failed: ${error.message}`,
2778:             },
2779:           ],
2780:         };
2781:       }
2782:     }
