83: /**
84:  * Resolve a caller-supplied import path and confine it to the exports
85:  * directory. Relative paths are resolved against the exports directory;
86:  * absolute paths are accepted only if they resolve (after following symlinks)
87:  * to a location inside the exports directory.
88:  *
89:  * Throws an Error whose message is safe to surface to the caller — it never
90:  * contains any bytes read from the target file.
91:  */
92: function resolveConfinedImportPath(filePath: unknown): string {
93:   if (typeof filePath !== 'string' || filePath.length === 0) {
94:     throw new Error('filePath is required and must be a non-empty string');
95:   }
96: 
97:   // Resolve relative paths against the exports directory; leave absolute as-is.
98:   const candidate = path.resolve(exportsDirReal, filePath);
99: 
100:   // realpathSync follows symlinks and requires the file to exist; an attacker
101:   // cannot use a symlink inside the exports dir to escape it. statSync on the
102:   // resolved path then tells us it is a regular file of acceptable size.
103:   let resolved: string;
104:   let stats: fs.Stats;
105:   try {
106:     resolved = fs.realpathSync(candidate);
107:     stats = fs.statSync(resolved);
108:   } catch {
109:     throw new Error('import file not found in the exports directory');
110:   }
111: 
112:   // Use the SAME message as the not-found case so a file that exists outside
113:   // the exports directory is indistinguishable from a missing one (no
114:   // existence oracle), and never echo the resolved absolute path.
115:   const withinExports =
116:     resolved === exportsDirReal || resolved.startsWith(exportsDirReal + path.sep);
117:   if (!withinExports) {
118:     throw new Error('import file not found in the exports directory');
119:   }
120: 
121:   if (!stats.isFile()) {
122:     throw new Error('import path must be a regular file');
123:   }
124: 
125:   if (stats.size > MAX_IMPORT_BYTES) {
126:     throw new Error(`import file exceeds the maximum allowed size (${MAX_IMPORT_BYTES} bytes)`);
127:   }
128: 
129:   return resolved;
130: }
