216: // Pagination validation utility
217: interface PaginationParams {
218:   limit?: any;
219:   offset?: any;
220: }
221: 
222: interface ValidatedPagination {
223:   limit: number;
224:   offset: number;
225:   errors: string[];
226: }
227: 
228: function validatePaginationParams(params: PaginationParams): ValidatedPagination {
229:   const errors: string[] = [];
230:   let limit = 25; // default
231:   let offset = 0; // default
232: 
233:   // Validate limit
234:   if (params.limit !== undefined && params.limit !== null) {
235:     const rawLimit = params.limit;
236:     if (!Number.isInteger(rawLimit) || rawLimit <= 0) {
237:       errors.push(`Invalid limit: expected positive integer, got ${typeof rawLimit} '${rawLimit}'`);
238:       debugLog(`Pagination validation: Invalid limit ${rawLimit}, using default ${limit}`);
239:     } else {
240:       limit = Math.min(Math.max(1, rawLimit), 100); // clamp between 1-100
241:       if (limit !== rawLimit) {
242:         debugLog(`Pagination validation: Clamped limit from ${rawLimit} to ${limit}`);
243:       }
244:     }
245:   }
246: 
247:   // Validate offset
248:   if (params.offset !== undefined && params.offset !== null) {
249:     const rawOffset = params.offset;
250:     if (!Number.isInteger(rawOffset) || rawOffset < 0) {
251:       errors.push(
252:         `Invalid offset: expected non-negative integer, got ${typeof rawOffset} '${rawOffset}'`
253:       );
254:       debugLog(`Pagination validation: Invalid offset ${rawOffset}, using default ${offset}`);
255:     } else {
256:       offset = rawOffset;
257:     }
258:   }
259: 
260:   return { limit, offset, errors };
261: }
