314: // Helper to parse relative time strings
315: function parseRelativeTime(relativeTime: string): string | null {
316:   const now = new Date();
317:   const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
318: 
319:   if (relativeTime === 'today') {
320:     return today.toISOString();
321:   } else if (relativeTime === 'yesterday') {
322:     return new Date(today.getTime() - 24 * 60 * 60 * 1000).toISOString();
323:   } else if (relativeTime.match(/^(\d+) hours? ago$/)) {
324:     const hours = parseInt(relativeTime.match(/^(\d+)/)![1]);
325:     return new Date(now.getTime() - hours * 60 * 60 * 1000).toISOString();
326:   } else if (relativeTime.match(/^(\d+) days? ago$/)) {
327:     const days = parseInt(relativeTime.match(/^(\d+)/)![1]);
328:     return new Date(now.getTime() - days * 24 * 60 * 60 * 1000).toISOString();
329:   } else if (relativeTime === 'this week') {
330:     const startOfWeek = new Date(today);
331:     startOfWeek.setDate(today.getDate() - today.getDay());
332:     return startOfWeek.toISOString();
333:   } else if (relativeTime === 'last week') {
334:     const startOfLastWeek = new Date(today);
335:     startOfLastWeek.setDate(today.getDate() - today.getDay() - 7);
336:     return startOfLastWeek.toISOString();
337:   }
338: 
339:   return null;
340: }
