388: // Helper to create summary
389: function createSummary(
390:   items: any[],
391:   options: { categories?: string[]; maxLength?: number }
392: ): string {
393:   const { categories, maxLength = 1000 } = options;
394: 
395:   let filteredItems = items;
396:   if (categories && categories.length > 0) {
397:     filteredItems = items.filter(item => categories.includes(item.category));
398:   }
399: 
400:   // Group by category
401:   const grouped: Record<string, any[]> = filteredItems.reduce(
402:     (acc, item) => {
403:       const cat = item.category || 'uncategorized';
404:       if (!acc[cat]) acc[cat] = [];
405:       acc[cat].push(item);
406:       return acc;
407:     },
408:     {} as Record<string, any[]>
409:   );
410: 
411:   // Build summary
412:   let summary = '# Context Summary\n\n';
413: 
414:   // High priority items first
415:   const highPriorityItems = filteredItems.filter(item => item.priority === 'high');
416:   if (highPriorityItems.length > 0) {
417:     summary += '## High Priority Items\n';
418:     highPriorityItems.forEach(item => {
419:       summary += `- **${item.key}**: ${item.value.substring(0, 200)}${item.value.length > 200 ? '...' : ''}\n`;
420:     });
421:     summary += '\n';
422:   }
423: 
424:   // Then by category
425:   Object.entries(grouped).forEach(([category, categoryItems]) => {
426:     if (category !== 'uncategorized') {
427:       summary += `## ${category.charAt(0).toUpperCase() + category.slice(1)}\n`;
428:       categoryItems.forEach((item: any) => {
429:         if (item.priority !== 'high') {
430:           // Already shown above
431:           summary += `- ${item.key}: ${item.value.substring(0, 100)}${item.value.length > 100 ? '...' : ''}\n`;
432:         }
433:       });
434:       summary += '\n';
435:     }
436:   });
437: 
438:   // Truncate if needed
439:   if (summary.length > maxLength) {
440:     summary = summary.substring(0, maxLength - 3) + '...';
441:   }
442: 
443:   return summary;
444: }
