1710:       // Check if session exists
1711:       const session = db.prepare('SELECT * FROM sessions WHERE id = ?').get(targetSessionId) as any;
1712:       if (!session) {
1713:         throw new Error(`Session not found: ${targetSessionId}`);
1714:       }
