1798: - Cached Files: ${stats.files}
1799: - Checkpoints: ${stats.checkpoints}
1800: - Export Size: ${(stats.size / 1024).toFixed(2)} KB
1801: 
1802: Session ID: ${targetSessionId}`
1803:                   : `Exported session to: ${exportPath}
1804: Items: ${stats.items}
1805: Files: ${stats.files}`) + sizeWarning,
1806:             },
