1829:     case 'context_import': {
1830:       const { filePath, merge = false } = args;
1831: 
1832:       // Confine the path to the server-owned exports directory BEFORE touching
1833:       // the filesystem. A failure here is a path/permission problem, never file
1834:       // content, so the message is safe to return verbatim.
1835:       let safePath: string;
1836:       try {
1837:         safePath = resolveConfinedImportPath(filePath);
1838:       } catch (error: any) {
1839:         return {
1840:           content: [{ type: 'text', text: `Import failed: ${error.message}` }],
1841:         };
1842:       }
1843: 
1844:       // Read and parse separately so a JSON.parse error can never echo file
1845:       // bytes back to the caller (V8 includes the offending input in its
1846:       // SyntaxError message).
1847:       let importData: any;
1848:       try {
1849:         const raw = fs.readFileSync(safePath, 'utf8');
1850:         try {
1851:           importData = JSON.parse(raw);
1852:         } catch {
1853:           return {
1854:             content: [{ type: 'text', text: 'Import failed: file is not valid JSON export data' }],
1855:           };
1856:         }
1857:       } catch {
1858:         return {
1859:           content: [{ type: 'text', text: 'Import failed: could not read import file' }],
1860:         };
1861:       }
1862: 
1863:       // Validate the import has the expected shape before using it.
1864:       if (
1865:         typeof importData !== 'object' ||
1866:         importData === null ||
1867:         typeof importData.session !== 'object' ||
1868:         importData.session === null ||
1869:         typeof importData.session.name !== 'string' ||
1870:         !Array.isArray(importData.contextItems)
1871:       ) {
1872:         return {
1873:           content: [
1874:             {
1875:               type: 'text',
1876:               text: 'Import failed: file is not a valid memory-keeper export (missing session or contextItems)',
1877:             },
1878:           ],
1879:         };
1880:       }
1881: 
1882:       // Merge only when there is actually a session to merge into; otherwise
1883:       // fall back to creating a new session (and report that honestly).
1884:       const merged = merge && !!currentSessionId;
1885: 
1886:       const fileCacheEntries = Array.isArray(importData.fileCache) ? importData.fileCache : [];
1887: 
1888:       // Bound the work before opening the (synchronous, event-loop-blocking)
1889:       // transaction so a huge row count cannot stall the server.
1890:       if (
1891:         importData.contextItems.length > MAX_IMPORT_ITEMS ||
1892:         fileCacheEntries.length > MAX_IMPORT_ITEMS
1893:       ) {
1894:         return {
1895:           content: [
1896:             {
1897:               type: 'text',
1898:               text: `Import failed: file exceeds the maximum allowed entry count (${MAX_IMPORT_ITEMS})`,
1899:             },
1900:           ],
1901:         };
1902:       }
1903: 
1904:       try {
1905:         // Apply the whole import atomically so a malformed row cannot leave an
1906:         // orphaned session or a partially-populated one behind. We do NOT mutate
1907:         // the module-level currentSessionId inside the transaction: better-sqlite3
1908:         // rolls back the database on error but cannot revert a JS assignment, so a
1909:         // post-assignment failure would leave currentSessionId dangling. Instead we
1910:         // return the new id and publish it only after the transaction commits.
1911:         const runImport = db.transaction(() => {
1912:           let targetSessionId: string;
1913:           const createdNew = !merged;
1914:           if (merged) {
1915:             targetSessionId = currentSessionId as string;
1916:           } else {
1917:             targetSessionId = uuidv4();
1918:             const importedSession = importData.session;
1919:             db.prepare(
1920:               `
1921:               INSERT INTO sessions (id, name, description, branch, working_directory, created_at)
1922:               VALUES (?, ?, ?, ?, ?, ?)
1923:             `
1924:             ).run(
1925:               targetSessionId,
1926:               `Imported: ${importedSession.name}`,
1927:               `Imported from ${safePath} on ${new Date().toISOString()}`,
1928:               typeof importedSession.branch === 'string' ? importedSession.branch : null,
1929:               null,
1930:               new Date().toISOString()
1931:             );
1932:           }
1933: 
1934:           // Import context items. Restore the channel/is_private/metadata columns
1935:           // too so a round trip is faithful, not lossy.
1936:           const itemStmt = db.prepare(`
1937:             INSERT OR REPLACE INTO context_items (id, session_id, key, value, category, priority, size, metadata, is_private, channel, created_at, updated_at)
1938:             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
1939:           `);
1940: 
1941:           let itemCount = 0;
1942:           let skippedItems = 0;
1943:           for (const item of importData.contextItems) {
1944:             // Skip entries that are not well-formed items rather than letting a
1945:             // bad row abort the whole transaction with a SQLite binding error.
1946:             if (
1947:               typeof item !== 'object' ||
1948:               item === null ||
1949:               typeof item.key !== 'string' ||
1950:               typeof item.value !== 'string'
1951:             ) {
1952:               skippedItems++;
1953:               continue;
1954:             }
1955:             itemStmt.run(
1956:               uuidv4(),
1957:               targetSessionId,
1958:               item.key,
1959:               item.value,
1960:               typeof item.category === 'string' ? item.category : null,
1961:               typeof item.priority === 'string' ? item.priority : null,
1962:               // Use the stored size only when it is a valid non-negative number;
1963:               // `|| calculateSize(...)` would wrongly recompute a legitimate 0.
1964:               typeof item.size === 'number' && item.size >= 0
1965:                 ? item.size
1966:                 : calculateSize(item.value),
1967:               typeof item.metadata === 'string' ? item.metadata : null,
1968:               typeof item.is_private === 'number' ? item.is_private : 0,
1969:               typeof item.channel === 'string' ? item.channel : 'general',
1970:               typeof item.created_at === 'string' ? item.created_at : new Date().toISOString()
1971:             );
1972:             itemCount++;
1973:           }
1974: 
1975:           // Import file cache. content is a nullable column, so null is valid and
1976:           // must NOT be treated as a malformed row (that would drop legit rows).
1977:           const fileStmt = db.prepare(`
1978:             INSERT OR REPLACE INTO file_cache (id, session_id, file_path, content, hash, last_read)
1979:             VALUES (?, ?, ?, ?, ?, ?)
1980:           `);
1981: 
1982:           let fileCount = 0;
1983:           let skippedFiles = 0;
1984:           for (const file of fileCacheEntries) {
1985:             if (
1986:               typeof file !== 'object' ||
1987:               file === null ||
1988:               typeof file.file_path !== 'string' ||
1989:               (file.content !== null && typeof file.content !== 'string')
1990:             ) {
1991:               skippedFiles++;
1992:               continue;
