2895: 
2896:       try {
2897:         // Build query for items to compress
2898:         let query = 'SELECT * FROM context_items WHERE session_id = ?';
2899:         const params: any[] = [targetSessionId];
2900: 
2901:         if (olderThan) {
2902:           query += ' AND created_at < ?';
2903:           params.push(olderThan);
2904:         }
2905: 
2906:         if (preserveCategories.length > 0) {
2907:           query += ` AND category NOT IN (${preserveCategories.map(() => '?').join(',')})`;
2908:           params.push(...preserveCategories);
2909:         }
2910: 
2911:         const itemsToCompress = db.prepare(query).all(...params) as any[];
2912: 
2913:         if (itemsToCompress.length === 0) {
2914:           return {
2915:             content: [
