2917:                 type: 'text',
2918:                 text: 'No items found to compress with given criteria.',
2919:               },
2920:             ],
2921:           };
2922:         }
2923: 
2924:         // Group items by category for compression
2925:         const categoryGroups: Record<string, any[]> = {};
2926:         for (const item of itemsToCompress) {
2927:           const category = item.category || 'uncategorized';
2928:           if (!categoryGroups[category]) {
2929:             categoryGroups[category] = [];
2930:           }
2931:           categoryGroups[category].push(item);
2932:         }
2933: 
2934:         // Compress each category group
2935:         const compressed: any[] = [];
2936:         for (const [category, items] of Object.entries(categoryGroups)) {
2937:           const summary = {
2938:             category,
2939:             count: items.length,
2940:             priorities: { high: 0, normal: 0, low: 0 },
2941:             keys: items.map((i: any) => i.key),
2942:             samples: items
2943:               .slice(0, 3)
2944:               .map((i: any) => ({ key: i.key, value: i.value.substring(0, 100) })),
2945:           };
2946: 
2947:           for (const item of items) {
2948:             const priority = (item.priority || 'normal') as 'high' | 'normal' | 'low';
2949:             summary.priorities[priority]++;
2950:           }
2951: 
2952:           compressed.push(summary);
2953:         }
2954: 
2955:         // Calculate compression
2956:         const originalSize = JSON.stringify(itemsToCompress).length;
2957:         const compressedData = JSON.stringify(compressed);
2958:         const compressedSize = compressedData.length;
2959:         const compressionRatio = 1 - compressedSize / originalSize;
2960: 
2961:         // Store compressed data
2962:         const compressedId = uuidv4();
2963:         const dateRange = itemsToCompress.reduce(
2964:           (acc, item) => {
2965:             const date = new Date(item.created_at);
2966:             if (!acc.start || date < acc.start) acc.start = date;
2967:             if (!acc.end || date > acc.end) acc.end = date;
2968:             return acc;
2969:           },
2970:           { start: null as Date | null, end: null as Date | null }
2971:         );
2972: 
2973:         db.prepare(
2974:           `
2975:           INSERT INTO compressed_context (id, session_id, original_count, compressed_data, compression_ratio, date_range_start, date_range_end)
2976:           VALUES (?, ?, ?, ?, ?, ?, ?)
2977:         `
2978:         ).run(
2979:           compressedId,
2980:           targetSessionId,
2981:           itemsToCompress.length,
2982:           compressedData,
2983:           compressionRatio,
2984:           dateRange.start?.toISOString(),
2985:           dateRange.end?.toISOString()
2986:         );
2987: 
2988:         // Delete original items
2989:         const deleteStmt = db.prepare('DELETE FROM context_items WHERE id = ?');
2990:         for (const item of itemsToCompress) {
2991:           deleteStmt.run(item.id);
2992:         }
2993: 
2994:         return {
2995:           content: [
2996:             {
2997:               type: 'text',
2998:               text: `Compression completed!
2999: Items compressed: ${itemsToCompress.length}
3000: Original size: ${(originalSize / 1024).toFixed(2)} KB
3001: Compressed size: ${(compressedSize / 1024).toFixed(2)} KB
3002: Compression ratio: ${(compressionRatio * 100).toFixed(1)}%
3003: Date range: ${dateRange.start?.toISOString().substring(0, 10)} to ${dateRange.end?.toISOString().substring(0, 10)}
3004: 
3005: Categories compressed:
3006: ${Object.entries(categoryGroups)
3007:   .map(([cat, items]) => `- ${cat}: ${items.length} items`)
3008:   .join('\n')}
3009: 
3010: Compressed data ID: ${compressedId.substring(0, 8)}`,
3011:             },
3012:           ],
3013:         };
3014:       } catch (error: any) {
