1: #!/usr/bin/env tsx
2: 
3: /**
4:  * Real-life test for the gzip decompression fix (issue #81).
5:  *
6:  * Sends actual HTTPS requests to real websites that serve gzip-encoded
7:  * responses and verifies the result is readable text — NOT raw gzip bytes.
8:  *
9:  * This script is intentionally NOT included in run-all.ts because:
10:  *   - It makes external network requests (unsuitable for CI without internet)
11:  *   - It is meant for manual local verification before pushing a fix
12:  *
13:  * Run with:
14:  *   npx tsx __tests__/real-life/test-gzip-fix.ts
15:  */
16: 
17: import { fetchAndConvertToMarkdown } from '../../src/url-reader.js';
18: import { createMockServer } from '../helpers/mock-server.js';
19: import { urlCache } from '../../src/cache.js';
20: 
21: const GZIP_MAGIC = '\x1f\x8b';
22: const PREVIEW_LENGTH = 400;
23: 
24: interface TestCase {
25:   name: string;
26:   url: string;
27:   expectedFragment?: string; // a string we expect somewhere in the markdown
28: }
29: 
30: const TEST_CASES: TestCase[] = [
31:   {
32:     name: 'Wikipedia — exact URL from issue #81 report',
33:     url: 'https://en.wikipedia.org/wiki/Firefly_(TV_series)',
34:     expectedFragment: 'Firefly',
35:   },
36:   {
37:     name: 'example.com — baseline HTTPS',
38:     url: 'https://example.com',
39:     expectedFragment: 'Example Domain',
40:   },
41: ];
42: 
43: // ─── helpers ─────────────────────────────────────────────────────────────────
44: 
45: function pass(msg: string): void {
46:   console.log(`  ✅ ${msg}`);
47: }
48: 
49: function fail(msg: string): void {
50:   console.error(`  ❌ ${msg}`);
51: }
52: 
53: // ─── main ─────────────────────────────────────────────────────────────────────
54: 
55: async function runRealLifeTests(): Promise<boolean> {
56:   console.log('═══════════════════════════════════════════════════');
57:   console.log('  Real-life gzip decompression test  (issue #81)');
58:   console.log('═══════════════════════════════════════════════════\n');
59: 
60:   const mockServer = createMockServer();
61:   let allPassed = true;
62: 
63:   for (const tc of TEST_CASES) {
64:     console.log(`Test: ${tc.name}`);
65:     console.log(`  URL: ${tc.url}`);
66:     urlCache.clear();
67: 
68:     let result: string;
69:     try {
70:       result = await fetchAndConvertToMarkdown(mockServer as any, tc.url, 30_000);
71:     } catch (err: any) {
72:       fail(`fetchAndConvertToMarkdown threw: ${err.message}`);
73:       allPassed = false;
74:       console.log();
75:       continue;
76:     }
77: 
78:     // Must be a non-empty string
79:     if (typeof result !== 'string' || result.length === 0) {
80:       fail('Result is empty');
81:       allPassed = false;
82:       console.log();
83:       continue;
84:     }
85:     pass(`Result is a non-empty string (${result.length} chars)`);
86: 
87:     // Must NOT start with gzip magic bytes
88:     if (result.startsWith(GZIP_MAGIC)) {
89:       fail('Result starts with raw gzip magic bytes \\x1f\\x8b — decompression failed!');
90:       allPassed = false;
91:     } else {
92:       pass('Result does NOT start with gzip magic bytes');
93:     }
94: 
95:     // Must contain expected fragment (if provided)
96:     if (tc.expectedFragment) {
97:       if (result.includes(tc.expectedFragment)) {
98:         pass(`Result contains expected fragment: "${tc.expectedFragment}"`);
99:       } else {
100:         fail(`Result is missing expected fragment: "${tc.expectedFragment}"`);
101:         allPassed = false;
102:       }
103:     }
104: 
105:     // Print a preview for visual inspection
106:     console.log('\n  --- First ~400 characters of result ---');
107:     console.log(result.slice(0, PREVIEW_LENGTH).replace(/\n/g, '\n  '));
108:     console.log('  ---\n');
109:   }
110: 
111:   console.log('═══════════════════════════════════════════════════');
112:   if (allPassed) {
113:     console.log('  All real-life tests PASSED ✅');
114:   } else {
115:     console.log('  Some real-life tests FAILED ❌');
116:   }
117:   console.log('═══════════════════════════════════════════════════');
118: 
119:   return allPassed;
120: }
121: 
122: runRealLifeTests().then((ok) => {
123:   process.exit(ok ? 0 : 1);
124: }).catch((err) => {
125:   console.error('Unexpected error:', err);
126:   process.exit(1);
127: });

