1: #!/usr/bin/env tsx
2: 
3: /**
4:  * Unit Tests: url-reader.ts
5:  *
6:  * Tests for URL fetching and markdown conversion.
7:  *
8:  * Uses real local HTTP servers instead of global-fetch mocks so the tests
9:  * exercise the actual undici + Agent dispatch pipeline — including the
10:  * Content-Encoding decompression path that was broken by issue #81.
11:  */
12: 
13: import { strict as assert } from 'node:assert';
14: import * as http from 'node:http';
15: import * as net from 'node:net';
16: import * as zlib from 'node:zlib';
17: import { fetchAndConvertToMarkdown } from '../../src/url-reader.js';
18: import { urlCache } from '../../src/cache.js';
19: import { testFunction, createTestResults, printTestSummary } from '../helpers/test-utils.js';
20: import { createMockServer } from '../helpers/mock-server.js';
21: import { EnvManager } from '../helpers/env-utils.js';
22: 
23: const results = createTestResults();
24: const envManager = new EnvManager();
25: 
26: // ─── local test-server helpers ───────────────────────────────────────────────
27: 
28: type ServerOpts = {
29:   status?: number;
30:   headers?: Record<string, string>;
31:   body?: string | Buffer;
32:   /** Destroy the socket immediately — simulates ECONNRESET / hard close. */
33:   closeImmediately?: boolean;
34:   /** Accept the connection but never write anything — simulates a hung server. */
35:   hangForever?: boolean;
36: };
37: 
38: interface TestServer {
39:   url: string;
40:   close: () => Promise<void>;
41: }
42: 
43: function startTestServer(opts: ServerOpts = {}): Promise<TestServer> {
44:   return new Promise((resolve, reject) => {
45:     const server = http.createServer((req, res) => {
46:       if (opts.closeImmediately) {
47:         req.socket.destroy();
48:         return;
49:       }
50:       if (opts.hangForever) {
51:         // keep the socket open but never send any bytes
52:         return;
53:       }
54:       const status = opts.status ?? 200;
55:       const headers: Record<string, string> = {
56:         'content-type': 'text/html; charset=utf-8',
57:         ...opts.headers,
58:       };
59:       res.writeHead(status, headers);
60:       res.end(opts.body ?? '');
61:     });
62: 
63:     server.listen(0, '127.0.0.1', () => {
64:       const addr = server.address() as net.AddressInfo;
65:       resolve({
66:         url: `http://127.0.0.1:${addr.port}`,
67:         close: () =>
68:           new Promise<void>((res) => {
69:             server.closeAllConnections(); // drop any lingering (hung) connections
70:             server.close(() => res());
71:           }),
72:       });
73:     });
74: 
75:     server.once('error', reject);
76:   });
77: }
78: 
79: /**
80:  * Grab a free TCP port (open a server on port 0, record the assigned port,
81:  * then close it). Connecting to this port right after will get ECONNREFUSED.
82:  */
83: function getFreePort(): Promise<number> {
84:   return new Promise((resolve, reject) => {
85:     const srv = net.createServer();
86:     srv.listen(0, '127.0.0.1', () => {
87:       const port = (srv.address() as net.AddressInfo).port;
88:       srv.close(() => resolve(port));
89:     });
90:     srv.once('error', reject);
91:   });
92: }
93: 
94: // ─── tests ───────────────────────────────────────────────────────────────────
95: 
96: async function runTests() {
97:   console.log('🧪 Testing: url-reader.ts\n');
98: 
99:   // ── invalid URLs (blocked before any network call) ────────────────────────
100: 
101:   await testFunction('Error handling for invalid URL', async () => {
