493:         <h2>API v100 referencex</h2><p>Regex-like near miss should not be selected.</p>
494:       </body></html>
495:     `;
496:     const { url, close } = await startTestServer({ body: testHtml });
497:     try {
498:       const result = await fetchAndConvertToMarkdown(mockServer as any, url, 10000, {
499:         section: 'API (v1.0+) reference?',
500:       });
501:       assert.ok(
502:         result.includes('API (v1.0+) reference?'),
503:         `Expected literal heading match, got: ${result}`,
504:       );
505:       assert.ok(
506:         result.includes('Literal metacharacter heading content'),
507:         `Expected matching section body, got: ${result}`,
508:       );
509:       assert.ok(
510:         !result.includes('Regex-like near miss'),
511:         'Expected regex-like near miss to be excluded',
512:       );
513:     } finally {
514:       await close();
515:     }
516:   }, results);
517: 
518:   // ── paragraph range ───────────────────────────────────────────────────────
519: 
520:   await testFunction('Paragraph range - single paragraph', async () => {
521:     const mockServer = createMockServer();
522:     urlCache.clear();
523: 
524:     const testHtml =
525:       '<html><body><p>First paragraph.</p><p>Second paragraph.</p><p>Third paragraph.</p></body></html>';
526:     const { url, close } = await startTestServer({ body: testHtml });
527:     try {
528:       const result = await fetchAndConvertToMarkdown(mockServer as any, url, 10000, {
529:         paragraphRange: '1',
530:       });
531:       assert.ok(result.includes('First paragraph'), `Expected first paragraph, got: ${result}`);
532:       assert.ok(!result.includes('Second paragraph'), `Expected only first paragraph`);
533:     } finally {
534:       await close();
535:     }
536:   }, results);
537: 
538:   await testFunction('Paragraph range - specific range', async () => {
539:     const mockServer = createMockServer();
540:     urlCache.clear();
541: 
542:     const testHtml =
543:       '<html><body><p>Para one.</p><p>Para two.</p><p>Para three.</p><p>Para four.</p></body></html>';
544:     const { url, close } = await startTestServer({ body: testHtml });
545:     try {
546:       const result = await fetchAndConvertToMarkdown(mockServer as any, url, 10000, {
547:         paragraphRange: '2-3',
548:       });
549:       assert.ok(result.includes('Para two'), `Expected para two, got: ${result}`);
550:       assert.ok(result.includes('Para three'), `Expected para three, got: ${result}`);
551:       assert.ok(!result.includes('Para one'), `Expected para one excluded`);
552:     } finally {
553:       await close();
554:     }
555:   }, results);
556: 
557:   await testFunction('Paragraph range - range to end', async () => {
558:     const mockServer = createMockServer();
559:     urlCache.clear();
560: 
561:     const testHtml =
562:       '<html><body><p>Alpha.</p><p>Beta.</p><p>Gamma.</p></body></html>';
563:     const { url, close } = await startTestServer({ body: testHtml });
564:     try {
565:       const result = await fetchAndConvertToMarkdown(mockServer as any, url, 10000, {
566:         paragraphRange: '2-',
567:       });
568:       assert.ok(result.includes('Beta'), `Expected Beta, got: ${result}`);
569:       assert.ok(result.includes('Gamma'), `Expected Gamma, got: ${result}`);
570:       assert.ok(!result.includes('Alpha'), `Expected Alpha excluded`);
571:     } finally {
572:       await close();
573:     }
574:   }, results);
575: 
576:   await testFunction('Paragraph range - out of bounds returns message', async () => {
577:     const mockServer = createMockServer();
578:     urlCache.clear();
579: 
580:     const testHtml = '<html><body><p>Only one paragraph.</p></body></html>';
581:     const { url, close } = await startTestServer({ body: testHtml });
582:     try {
583:       const result = await fetchAndConvertToMarkdown(mockServer as any, url, 10000, {
584:         paragraphRange: '99',
