616:       assert.ok(result.includes('Chapter One'), `Expected Chapter One, got: ${result}`);
617:       assert.ok(!result.includes('Some paragraph text'), `Paragraph should be excluded`);
618:     } finally {
619:       await close();
620:     }
621:   }, results);
622: 
623:   await testFunction('readHeadings with no headings returns message', async () => {
624:     const mockServer = createMockServer();
