634:         result.includes('No headings found'),
635:         `Expected "No headings found", got: ${result}`,
636:       );
637:     } finally {
638:       await close();
639:     }
640:   }, results);
641: 
642:   printTestSummary(results, 'URL Reader Module');
643:   return results;
644: }
645: 
646: // Run if executed directly
647: if (import.meta.url === `file://${process.argv[1]}`) {
648:   runTests().then(results => {
649:     process.exit(results.failed > 0 ? 1 : 0);
650:   }).catch(console.error);
651: }
652: 
653: export { runTests };
