1: import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
2: import { SearXNGWeb } from "./types.js";
3: import { createProxyAgent, createDefaultAgent, ProxyType } from "./proxy.js";
4: import { logMessage } from "./logging.js";
5: import {
6:   MCPSearXNGError,
7:   validateEnvironment,
8:   createNetworkError,
9:   createServerError,
10:   createJSONError,
11:   createDataError,
12:   createNoResultsMessage,
13:   type ErrorContext
14: } from "./error-handler.js";
15: 
16: export async function performWebSearch(
17:   mcpServer: McpServer,
18:   query: string,
19:   pageno: number = 1,
20:   time_range?: string,
21:   language: string = "all",
22:   safesearch?: number,
23:   min_score?: number
24: ) {
25:   const startTime = Date.now();
26:   
27:   // Build detailed log message with all parameters
28:   const searchParams = [
29:     `page ${pageno}`,
30:     `lang: ${language}`,
31:     time_range ? `time: ${time_range}` : null,
32:     safesearch ? `safesearch: ${safesearch}` : null
33:   ].filter(Boolean).join(", ");
34:   
35:   logMessage(mcpServer, "info", `Starting web search: "${query}" (${searchParams})`);
36:   
37:   const validationError = validateEnvironment();
38:   if (validationError) {
39:     logMessage(mcpServer, "error", "Configuration invalid");
40:     throw new MCPSearXNGError(validationError);
41:   }
42: 
43:   const searxngUrl = process.env.SEARXNG_URL!;
44:   const parsedUrl = new URL(searxngUrl.endsWith('/') ? searxngUrl : searxngUrl + '/');
45: 
46:   const url = new URL('search', parsedUrl);
47: 
48:   url.searchParams.set("q", query);
49:   url.searchParams.set("format", "json");
50:   url.searchParams.set("pageno", pageno.toString());
51: 
52:   if (
53:     time_range !== undefined &&
54:     ["day", "week", "month", "year"].includes(time_range)
55:   ) {
56:     url.searchParams.set("time_range", time_range);
57:   }
58: 
59:   if (language && language !== "all") {
60:     url.searchParams.set("language", language);
61:   }
62: 
63:   if (safesearch !== undefined && [0, 1, 2].includes(safesearch)) {
64:     url.searchParams.set("safesearch", safesearch.toString());
65:   }
66: 
67:   // Prepare request options with headers
68:   const requestOptions: RequestInit = {
69:     method: "GET"
70:   };
71: 
72:   // Add proxy or default dispatcher (includes system CA certs for TLS)
73:   const proxyAgent = createProxyAgent(url.toString(), ProxyType.SEARCH);
74:   const dispatcher = proxyAgent ?? createDefaultAgent();
75:   if (dispatcher) {
76:     (requestOptions as any).dispatcher = dispatcher;
77:   }
78: 
79:   // Add basic authentication if credentials are provided
80:   const username = process.env.AUTH_USERNAME;
81:   const password = process.env.AUTH_PASSWORD;
82: 
83:   if (username && password) {
84:     const base64Auth = Buffer.from(`${username}:${password}`).toString('base64');
85:     requestOptions.headers = {
86:       ...requestOptions.headers,
87:       'Authorization': `Basic ${base64Auth}`
88:     };
89:   }
90: 
91:   // Add User-Agent header if configured
92:   const userAgent = process.env.USER_AGENT;
93:   if (userAgent) {
94:     requestOptions.headers = {
95:       ...requestOptions.headers,
96:       'User-Agent': userAgent
97:     };
98:   }
99: 
100:   // Fetch with enhanced error handling
101:   let response: Response;
102:   try {
103:     logMessage(mcpServer, "info", `Making request to: ${url.toString()}`);
104:     response = await fetch(url.toString(), requestOptions);
105:   } catch (error: any) {
106:     logMessage(mcpServer, "error", `Network error during search request: ${error.message}`, { query, url: url.toString() });
107:     const context: ErrorContext = {
108:       url: url.toString(),
109:       searxngUrl,
110:       proxyAgent: !!dispatcher,
111:       username
112:     };
113:     throw createNetworkError(error, context);
114:   }
115: 
116:   if (!response.ok) {
117:     let responseBody: string;
118:     try {
119:       responseBody = await response.text();
120:     } catch {
121:       responseBody = '[Could not read response body]';
122:     }
123: 
124:     const context: ErrorContext = {
125:       url: url.toString(),
126:       searxngUrl
127:     };
128:     throw createServerError(response.status, response.statusText, responseBody, context);
129:   }
130: 
131:   // Parse JSON response
132:   let data: SearXNGWeb;
133:   try {
134:     data = (await response.json()) as SearXNGWeb;
135:   } catch (error: any) {
136:     let responseText: string;
137:     try {
138:       responseText = await response.text();
139:     } catch {
140:       responseText = '[Could not read response text]';
141:     }
142: 
143:     const context: ErrorContext = { url: url.toString() };
144:     throw createJSONError(responseText, context);
145:   }
146: 
147:   if (!data.results) {
148:     const context: ErrorContext = { url: url.toString(), query };
149:     throw createDataError(data, context);
150:   }
151: 
152:   const results = data.results
153:     .map((result) => ({
154:       title: result.title || "",
155:       content: result.content || "",
156:       url: result.url || "",
157:       score: result.score || 0,
158:     }))
159:     .filter((result) => min_score === undefined || result.score >= min_score);
160: 
161:   if (results.length === 0) {
162:     const filterNote = min_score === undefined ? "" : ` after applying min_score=${min_score}`;
163:     logMessage(mcpServer, "info", `No results found for query: "${query}"${filterNote}`);
164:     return createNoResultsMessage(query);
165:   }
166: 
167:   const duration = Date.now() - startTime;
168:   logMessage(mcpServer, "info", `Search completed: "${query}" (${searchParams}) - ${results.length} results in ${duration}ms`);
169: 
170:   return results
171:     .map((r) => `Title: ${r.title}\nDescription: ${r.content}\nURL: ${r.url}\nRelevance Score: ${r.score.toFixed(3)}`)
172:     .join("\n\n");
173: }

