98: function applyCharacterPagination(content: string, startChar: number = 0, maxLength?: number): string {
99:   if (startChar >= content.length) {
100:     return "";
101:   }
102: 
103:   const start = Math.max(0, startChar);
104:   const end = maxLength ? Math.min(content.length, start + maxLength) : content.length;
105: 
106:   return content.slice(start, end);
