109: function extractSection(markdownContent: string, sectionHeading: string): string {
110:   const lines = markdownContent.split('\n');
111:   const normalizedHeading = sectionHeading.toLowerCase();
112: 
113:   let startIndex = -1;
114:   let currentLevel = 0;
115: 
116:   // Find the section start — string match avoids RegExp constructor with user input
117:   for (let i = 0; i < lines.length; i++) {
118:     const line = lines[i];
119:     if (/^#{1,6}\s/.test(line) && line.toLowerCase().includes(normalizedHeading)) {
120:       startIndex = i;
121:       currentLevel = (line.match(/^#+/) || [''])[0].length;
122:       break;
123:     }
124:   }
125: 
126:   if (startIndex === -1) {
127:     return "";
128:   }
129: 
130:   // Find the section end (next heading of same or higher level)
131:   let endIndex = lines.length;
132:   for (let i = startIndex + 1; i < lines.length; i++) {
133:     const line = lines[i];
134:     const match = line.match(/^#+/);
135:     if (match && match[0].length <= currentLevel) {
136:       endIndex = i;
137:       break;
138:     }
139:   }
140: 
141:   return lines.slice(startIndex, endIndex).join('\n');
142: }
143: 
144: function extractParagraphRange(markdownContent: string, range: string): string {
145:   const paragraphs = markdownContent.split('\n\n').filter(p => p.trim().length > 0);
146: 
147:   // Parse range (e.g., "1-5", "3", "10-")
148:   // eslint-disable-next-line security/detect-unsafe-regex
149:   const rangeMatch = range.match(/^(\d+)(?:-(\d*))?$/);
150:   if (!rangeMatch) {
151:     return "";
152:   }
153: 
154:   const start = parseInt(rangeMatch[1]) - 1; // Convert to 0-based index
155:   const endStr = rangeMatch[2];
156: 
157:   if (start < 0 || start >= paragraphs.length) {
158:     return "";
159:   }
160: 
161:   if (endStr === undefined) {
162:     // Single paragraph (e.g., "3")
163:     return paragraphs[start] || "";
164:   } else if (endStr === "") {
165:     // Range to end (e.g., "10-")
166:     return paragraphs.slice(start).join('\n\n');
167:   } else {
168:     // Specific range (e.g., "1-5")
169:     const end = parseInt(endStr);
170:     return paragraphs.slice(start, end).join('\n\n');
171:   }
172: }
173: 
174: function extractHeadings(markdownContent: string): string {
175:   const lines = markdownContent.split('\n');
176:   const headings = lines.filter(line => /^#{1,6}\s/.test(line));
177: 
178:   if (headings.length === 0) {
179:     return "No headings found in the content.";
180:   }
181: 
182:   return headings.join('\n');
183: }
184: 
185: function applyPaginationOptions(markdownContent: string, options: PaginationOptions): string {
186:   let result = markdownContent;
187: 
188:   // Apply heading extraction first if requested
189:   if (options.readHeadings) {
190:     return extractHeadings(result);
191:   }
192: 
193:   // Apply section extraction
194:   if (options.section) {
195:     result = extractSection(result, options.section);
196:     if (result === "") {
197:       return `Section "${options.section}" not found in the content.`;
198:     }
199:   }
200: 
201:   // Apply paragraph range filtering
202:   if (options.paragraphRange) {
203:     result = extractParagraphRange(result, options.paragraphRange);
204:     if (result === "") {
205:       return `Paragraph range "${options.paragraphRange}" is invalid or out of bounds.`;
206:     }
207:   }
208: 
209:   // Apply character-based pagination last
210:   if (options.startChar !== undefined || options.maxLength !== undefined) {
211:     result = applyCharacterPagination(result, options.startChar, options.maxLength);
212:   }
213: 
214:   return result;
215: }
