217: export async function fetchAndConvertToMarkdown(
218:   mcpServer: McpServer,
219:   url: string,
220:   timeoutMs: number = 10000,
221:   paginationOptions: PaginationOptions = {}
222: ) {
223:   const startTime = Date.now();
224:   logMessage(mcpServer, "info", `Fetching URL: ${url}`);
225: 
226:   // Check cache first
227:   const cachedEntry = urlCache.get(url);
228:   if (cachedEntry) {
229:     logMessage(mcpServer, "info", `Using cached content for URL: ${url}`);
230:     const result = applyPaginationOptions(cachedEntry.markdownContent, paginationOptions);
231:     const duration = Date.now() - startTime;
232:     logMessage(mcpServer, "info", `Processed cached URL: ${url} (${result.length} chars in ${duration}ms)`);
233:     return result;
234:   }
235:   
236:   // Validate URL format
237:   let parsedUrl: URL;
238:   try {
239:     parsedUrl = new URL(url);
240:   } catch (error) {
241:     logMessage(mcpServer, "error", `Invalid URL format: ${url}`);
242:     throw createURLFormatError(url);
243:   }
244: 
245:   assertUrlAllowed(parsedUrl);
246: 
247:   // Create an AbortController instance
248:   const controller = new AbortController();
249:   const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
250: 
251:   try {
252:     // Prepare base request options with proxy support
253:     const requestOptions: RequestInit = {
254:       signal: controller.signal,
255:       redirect: "manual",
256:     };
257: 
258:     // Add User-Agent header if configured (URL_READER_USER_AGENT takes priority over USER_AGENT)
259:     const userAgent = process.env.URL_READER_USER_AGENT || process.env.USER_AGENT;
260:     if (userAgent) {
261:       requestOptions.headers = {
262:         ...requestOptions.headers,
263:         'User-Agent': userAgent
264:       };
265:     }
266: 
267:     let response!: Response;
268:     let currentUrl = parsedUrl;
269:     let usedDispatcher = false;
270:     try {
271:       for (let redirects = 0; redirects <= MAX_REDIRECTS; redirects++) {
272:         // Add proxy or default dispatcher (includes system CA certs for TLS)
273:         const proxyAgent = createProxyAgent(currentUrl.toString(), ProxyType.URL_READER);
274:         const dispatcher = proxyAgent ?? createDefaultAgent();
275:         usedDispatcher = !!dispatcher;
276:         const currentRequestOptions = {
277:           ...requestOptions,
278:         };
279:         if (dispatcher) {
280:           (currentRequestOptions as any).dispatcher = dispatcher;
281:         }
282: 
283:         // Fetch the URL with the abort signal.
284:         // Use undici's own fetch so it shares the same internal version as the
285:         // Agent/ProxyAgent dispatcher — avoids the Node.js bundled-undici vs
286:         // npm-undici version mismatch that breaks Content-Encoding decompression.
287:         response = await (undiciFetch as unknown as typeof fetch)(currentUrl.toString(), currentRequestOptions);
288: 
289:         if (!isRedirectResponse(response)) {
290:           break;
291:         }
292: 
293:         const location = response.headers.get("location");
294:         if (!location) {
295:           break;
296:         }
297: 
298:         if (redirects === MAX_REDIRECTS) {
299:           throw createContentError(`Too many redirects while fetching URL: ${url}`, url);
300:         }
301: 
302:         const nextUrl = new URL(location, currentUrl);
303:         assertUrlAllowed(nextUrl);
304:         currentUrl = nextUrl;
305:       }
306:     } catch (error: any) {
307:       if (error.name === 'MCPSearXNGError') {
308:         throw error;
309:       }
310: 
311:       const context: ErrorContext = {
312:         url: currentUrl.toString(),
313:         proxyAgent: usedDispatcher,
314:         timeout: timeoutMs
315:       };
316:       throw createNetworkError(error, context);
317:     }
318: 
319:     if (!response.ok) {
320:       let responseBody: string;
321:       try {
322:         responseBody = await response.text();
323:       } catch {
324:         responseBody = '[Could not read response body]';
325:       }
326: 
327:       const context: ErrorContext = { url };
328:       throw createServerError(response.status, response.statusText, responseBody, context);
329:     }
330: 
331:     // Retrieve HTML content
332:     let htmlContent: string;
333:     try {
334:       htmlContent = await response.text();
335:     } catch (error: any) {
336:       throw createContentError(
337:         `Failed to read website content: ${error.message || 'Unknown error reading content'}`,
338:         url
339:       );
340:     }
341: 
342:     if (!htmlContent || htmlContent.trim().length === 0) {
343:       throw createContentError("Website returned empty content.", url);
344:     }
345: 
346:     // Convert HTML to Markdown
347:     let markdownContent: string;
348:     try {
349:       markdownContent = NodeHtmlMarkdown.translate(htmlContent);
350:     } catch (error: any) {
351:       throw createConversionError(error, url, htmlContent);
352:     }
353: 
354:     if (!markdownContent || markdownContent.trim().length === 0) {
355:       logMessage(mcpServer, "warning", `Empty content after conversion: ${url}`);
356:       // DON'T cache empty/failed conversions - return warning directly
357:       return createEmptyContentWarning(url, htmlContent.length, htmlContent);
358:     }
359: 
360:     // Only cache successful markdown conversion
361:     urlCache.set(url, htmlContent, markdownContent);
362: 
363:     // Apply pagination options
364:     const result = applyPaginationOptions(markdownContent, paginationOptions);
365: 
366:     const duration = Date.now() - startTime;
367:     logMessage(mcpServer, "info", `Successfully fetched and converted URL: ${url} (${result.length} chars in ${duration}ms)`);
368:     return result;
369:   } catch (error: any) {
370:     if (error.name === "AbortError") {
371:       logMessage(mcpServer, "error", `Timeout fetching URL: ${url} (${timeoutMs}ms)`);
372:       throw createTimeoutError(timeoutMs, url);
373:     }
374:     // Re-throw our enhanced errors
375:     if (error.name === 'MCPSearXNGError') {
376:       logMessage(mcpServer, "error", `Error fetching URL: ${url} - ${error.message}`);
377:       throw error;
378:     }
379:     
380:     // Catch any unexpected errors
381:     logMessage(mcpServer, "error", `Unexpected error fetching URL: ${url}`, error);
382:     const context: ErrorContext = { url };
383:     throw createUnexpectedError(error, context);
384:   } finally {
385:     // Clean up the timeout to prevent memory leaks
386:     clearTimeout(timeoutId);
387:   }
388: }

