1: import { describe, it, expect, afterEach, jest } from "bun:test";
2: import { Fetcher } from "./Fetcher";
3: 
4: const sampleHtml = `<!DOCTYPE html>
5: <html>
6:   <head>
7:     <title>Test Page</title>
8:     <script>var x = 1;</script>
9:     <script src="app.js"></script>
10:     <style>body { color: red; }</style>
11:     <style>.hidden { display: none; }</style>
12:   </head>
13:   <body>
14:     <h1>Main Title</h1>
15:     <p>First paragraph with <a href="/link">a link</a>.</p>
16:     <ul>
17:       <li>Item one</li>
18:       <li>Item two</li>
19:     </ul>
20:     <div>
21:       <p>Nested paragraph.</p>
22:       <script>alert('inline script')</script>
23:     </div>
24:   </body>
25: </html>`;
26: 
27: function mockFetchWith(content: string, contentType = "text/html") {
28:   globalThis.fetch = jest.fn().mockResolvedValue({
29:     ok: true,
30:     text: () => Promise.resolve(content),
31:     json: () => Promise.resolve(JSON.parse(content)),
32:     headers: new Headers({ "content-type": contentType }),
33:   }) as any;
34: }
35: 
36: const originalFetch = globalThis.fetch;
37: 
38: describe("Fetcher — fixture tests", () => {
39:   afterEach(() => {
40:     globalThis.fetch = originalFetch;
41:   });
42: 
43:   const req = (overrides?: Partial<{ max_length: number; start_index: number }>) => ({
44:     url: "https://example.com",
45:     ...overrides,
46:   });
47: 
48:   describe("txt — real JSDOM parsing", () => {
49:     it("strips scripts, styles, and normalizes whitespace", async () => {
50:       mockFetchWith(sampleHtml);
51:       const result = await Fetcher.txt(req({ max_length: 0 }));
52:       const text = result.content[0].text;
53: 
54:       expect(text).not.toContain("var x = 1");
55:       expect(text).not.toContain("alert(");
56:       expect(text).not.toContain("color: red");
57:       expect(text).not.toContain("display: none");
58:       expect(text).toContain("Main Title");
59:       expect(text).toContain("First paragraph");
60:       expect(text).toContain("a link");
61:       expect(text).toContain("Item one");
62:       expect(text).toContain("Item two");
63:       expect(text).toContain("Nested paragraph");
64:       // whitespace normalized — no runs of multiple spaces
65:       expect(text).not.toMatch(/  /);
66:     });
67: 
68:     it("returns empty string for body-less HTML", async () => {
69:       mockFetchWith("<html><head><title>No body</title></head></html>");
70:       const result = await Fetcher.txt(req({ max_length: 0 }));
71:       expect(result.content[0].text).toBe("");
72:     });
73:   });
74: 
75:   describe("markdown — real Turndown conversion", () => {
76:     it("converts headings, links, and lists to markdown", async () => {
77:       mockFetchWith(sampleHtml);
78:       const result = await Fetcher.markdown(req({ max_length: 0 }));
79:       const md = result.content[0].text;
