1: #!/usr/bin/env node
2: 
3: import { Server } from "@modelcontextprotocol/sdk/server/index.js";
4: import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
5: import {
6:   CallToolRequestSchema,
7:   ListToolsRequestSchema,
8: } from "@modelcontextprotocol/sdk/types.js";
9: import { RequestPayloadSchema } from "./types.js";
10: import { Fetcher } from "./Fetcher.js";
11: import process from "process";
12: import { downloadLimit } from "./types.js";
13: 
14: const server = new Server(
15:   {
16:     name: "zcaceres/fetch",
17:     version: "0.1.0",
18:   },
19:   {
20:     capabilities: {
21:       resources: {},
22:       tools: {},
23:     },
24:   },
25: );
26: 
27: server.setRequestHandler(ListToolsRequestSchema, async () => {
28:   return {
29:     tools: [
30:       {
31:         name: "fetch_html",
32:         description: "Fetch a website and return its unmodified contents as HTML",
33:         inputSchema: {
34:           type: "object",
35:           properties: {
36:             url: {
37:               type: "string",
38:               description: "URL of the website to fetch",
39:             },
40:             headers: {
41:               type: "object",
42:               description: "Optional headers to include in the request",
43:             },
44:             max_length: {
45:               type: "number",
46:               description: `Maximum number of characters to return (default: ${downloadLimit})`,
47:             },
48:             start_index: {
49:               type: "number",
50:               description: "Start content from this character index (default: 0)",
51:             },
52:           },
53:           required: ["url"],
54:         },
55:       },
56:       {
57:         name: "fetch_markdown",
58:         description: "Fetch a website and return its contents converted content to Markdown",
59:         inputSchema: {
60:           type: "object",
61:           properties: {
62:             url: {
63:               type: "string",
64:               description: "URL of the website to fetch",
65:             },
66:             headers: {
67:               type: "object",
68:               description: "Optional headers to include in the request",
69:             },
70:             max_length: {
71:               type: "number",
72:               description: `Maximum number of characters to return (default: ${downloadLimit}})`,
73:             },
74:             start_index: {
75:               type: "number",
76:               description: "Start content from this character index (default: 0)",
77:             },
78:           },
79:           required: ["url"],
80:         },
81:       },
82:       {
83:         name: "fetch_txt",
84:         description:
85:           "Fetch a website, convert the content to plain text (no HTML)",
86:         inputSchema: {
87:           type: "object",
88:           properties: {
89:             url: {
90:               type: "string",
91:               description: "URL of the website to fetch",
92:             },
93:             headers: {
94:               type: "object",
95:               description: "Optional headers to include in the request",
96:             },
97:             max_length: {
98:               type: "number",
99:               description: `Maximum number of characters to return (default: ${downloadLimit})`,
100:             },
101:             start_index: {
102:               type: "number",
103:               description: "Start content from this character index (default: 0)",
104:             },
105:           },
106:           required: ["url"],
107:         },
108:       },
109:       {
110:         name: "fetch_json",
111:         description: "Fetch a JSON file from a URL",
112:         inputSchema: {
113:           type: "object",
114:           properties: {
115:             url: {
116:               type: "string",
117:               description: "URL of the JSON to fetch",
118:             },
119:             headers: {
120:               type: "object",
121:               description: "Optional headers to include in the request",
122:             },
123:             max_length: {
124:               type: "number",
125:               description: `Maximum number of characters to return (default: ${downloadLimit})`,
126:             },
127:             start_index: {
128:               type: "number",
129:               description: "Start content from this character index (default: 0)",
130:             },
131:           },
132:           required: ["url"],
133:         },
134:       },
135:     ],
136:   };
137: });
138: 
139: server.setRequestHandler(CallToolRequestSchema, async (request) => {
140:   const { name, arguments: args } = request.params;
141: 
142:   const validatedArgs = RequestPayloadSchema.parse(args);
143: 
144:   if (request.params.name === "fetch_html") {
145:     const fetchResult = await Fetcher.html(validatedArgs);
146:     return fetchResult;
147:   }
148:   if (request.params.name === "fetch_json") {
149:     const fetchResult = await Fetcher.json(validatedArgs);
150:     return fetchResult;
151:   }
152:   if (request.params.name === "fetch_txt") {
153:     const fetchResult = await Fetcher.txt(validatedArgs);
154:     return fetchResult;
155:   }
156:   if (request.params.name === "fetch_markdown") {
157:     const fetchResult = await Fetcher.markdown(validatedArgs);
158:     return fetchResult;
159:   }
160:   throw new Error("Tool not found");
161: });
162: 
163: async function main() {
164:   const transport = new StdioServerTransport();
165:   await server.connect(transport);
166: }
167: 
168: main().catch((error) => {
169:   console.error("Fatal error in main():", error);
170:   process.exit(1);
171: });

