64: function normalizeText(text: string): string {
65:     return text
66:         .replace(/\r\n/g, '\n')
67:         .replace(/\u00a0/g, ' ')
68:         .replace(/[ \t]+\n/g, '\n')
69:         .replace(/\n{3,}/g, '\n\n')
70:         .trim();
