123: function extractMainTextFromHtml(html: string): HtmlExtractionResult {
124:     const $ = cheerio.load(html);
125:     const title = $('title').first().text().trim();
126:     const metaDescription = $('meta[name="description"]').attr('content')?.trim() ||
127:         $('meta[property="og:description"]').attr('content')?.trim() ||
128:         '';
129: 
130:     $('script, style, noscript, template, iframe, svg, canvas').remove();
131: 
132:     const preferredContainers = [
133:         'article',
134:         'main',
135:         '[role="main"]',
136:         '.markdown-body',
137:         '.article-content',
138:         '.post-content',
139:         '.entry-content',
140:         '.content'
141:     ];
142: 
143:     let selectedText = '';
144:     let mode: HtmlExtractionResult['mode'] = 'metadata';
145:     for (const selector of preferredContainers) {
146:         const container = $(selector).first();
147:         if (container.length === 0) {
148:             continue;
149:         }
150: 
151:         const candidate = normalizeText(container.text());
152:         if (candidate.length >= 120) {
153:             selectedText = candidate;
154:             mode = 'container';
155:             break;
156:         }
157:     }
158: 
159:     if (!selectedText) {
160:         const body = $('body');
161:         selectedText = normalizeText((body.length > 0 ? body : $.root()).text());
162:         if (selectedText) {
163:             mode = 'body';
164:         }
165:     }
166: 
167:     // SPA pages often render content by JS and leave body nearly empty.
168:     // Fall back to metadata so callers still get useful page info.
169:     if (!selectedText) {
170:         selectedText = normalizeText([title, metaDescription].filter(Boolean).join('\n\n'));
171:         mode = 'metadata';
172:     }
173: 
174:     return { title, text: selectedText, mode };
175: }
