182: function extractReadableLinks(html: string, finalUrl: string): ExtractedLink[] {
183:     const dom = new JSDOM(html, { url: finalUrl });
184:     const anchors = Array.from(dom.window.document.querySelectorAll('a[href]'));
185:     const seen = new Set<string>();
186:     const links: ExtractedLink[] = [];
187: 
188:     for (const anchor of anchors) {
189:         const rawHref = anchor.getAttribute('href');
190:         if (!rawHref) {
191:             continue;
192:         }
193: 
194:         let href: string;
195:         try {
196:             href = new URL(rawHref, finalUrl).toString();
197:             assertPublicHttpUrl(href, 'Extracted link URL');
198:         } catch {
199:             continue;
200:         }
201: 
202:         if (seen.has(href)) {
203:             continue;
204:         }
205:         seen.add(href);
206: 
207:         links.push({
208:             text: normalizeText(anchor.textContent || ''),
209:             href
210:         });
211:     }
212: 
213:     return links;
214: }
