240: function shouldTryBrowserHtmlFallback(contentType: string, raw: string, extraction?: HtmlExtractionResult): boolean {
241:     if (looksLikeBotChallengePage(raw)) {
242:         return true;
243:     }
244: 
245:     if (contentType.includes('text/html') || looksLikeHtml(raw)) {
246:         return extraction?.mode === 'metadata' && extraction.text.length < MIN_METADATA_FALLBACK_CHARS;
247:     }
