288: async function tryRequestWithBrowserCookies(url: string): Promise<{ response?: any; usedBrowserCookies: boolean }> {
289:     let cookieHeader: string | undefined;
290:     try {
291:         cookieHeader = await getBrowserCookieHeader(url);
292:     } catch {
293:         return { response: undefined, usedBrowserCookies: false };
294:     }
295: 
296:     if (!cookieHeader) {
297:         return { response: undefined, usedBrowserCookies: false };
298:     }
299: 
300:     try {
301:         return {
302:             response: await axios.get(url, buildRequestOptions(cookieHeader)),
303:             usedBrowserCookies: true
304:         };
305:     } catch {
306:         return {
307:             response: undefined,
308:             usedBrowserCookies: true
309:         };
310:     }
311: }
