313: export async function fetchWebContent(
314:     url: string,
315:     maxChars: number = DEFAULT_MAX_CHARS,
316:     options: FetchWebContentOptions = {}
317: ): Promise<FetchWebContentResult> {
318:     const parsedUrl = new URL(url);
319:     assertPublicHttpUrl(parsedUrl, 'Request URL');
320: 
321:     const requestOptions = buildRequestOptions();
322: 
323:     // Pre-flight check to avoid downloading oversized payloads when Content-Length is present.
324:     try {
325:         const headResponse = await axios.head(parsedUrl.toString(), {
326:             ...requestOptions,
327:             responseType: 'json',
328:             validateStatus: (status: number) => status >= 200 && status < 400
329:         });
330:         const headLength = Number(headResponse.headers['content-length']);
331:         if (Number.isFinite(headLength) && headLength > MAX_DOWNLOAD_BYTES) {
332:             const tooLargeError = new Error(`Response body too large (${headLength} bytes). Max allowed is ${MAX_DOWNLOAD_BYTES} bytes`);
333:             (tooLargeError as any).code = 'ERR_RESPONSE_TOO_LARGE';
334:             throw tooLargeError;
335:         }
336:     } catch (error: any) {
337:         if (error?.code === 'ERR_RESPONSE_TOO_LARGE') {
338:             throw error;
339:         }
340:         const status = error?.response?.status;
341:         // Some servers don't support HEAD correctly; continue and rely on GET download limits.
342:         if (status !== undefined && ![400, 403, 404, 405, 406, 501].includes(status)) {
343:             throw error;
344:         }
345:     }
346: 
347:     let response: any;
348:     let usedBrowserCookies = false;
349:     let retrievalMethod: FetchWebContentResult['retrievalMethod'] = 'request';
350: 
351:     try {
352:         response = await axios.get(parsedUrl.toString(), requestOptions);
353:     } catch (error: any) {
354:         const status = error?.response?.status;
355:         if (![401, 403, 429].includes(status)) {
356:             throw error;
357:         }
358: 
359:         const cookieRetry = await tryRequestWithBrowserCookies(parsedUrl.toString());
360:         if (cookieRetry.response) {
361:             response = cookieRetry.response;
362:             usedBrowserCookies = cookieRetry.usedBrowserCookies;
363:             retrievalMethod = 'request-with-browser-cookies';
364:         } else {
365:             response = {
366:                 headers: { 'content-type': 'text/html; charset=utf-8' },
367:                 data: '',
368:                 request: { res: { responseUrl: parsedUrl.toString() } }
369:             };
370:         }
371:     }
372: 
373:     let contentType = String(response.headers['content-type'] || '').toLowerCase();
374:     let finalUrl = response.request?.res?.responseUrl || parsedUrl.toString();
375:     assertPublicHttpUrl(finalUrl, 'Final URL');
376:     let raw = typeof response.data === 'string'
377:         ? response.data
378:         : JSON.stringify(response.data, null, 2);
379: 
380:     if (!usedBrowserCookies && looksLikeBotChallengePage(raw)) {
381:         const cookieRetry = await tryRequestWithBrowserCookies(parsedUrl.toString());
382:         if (cookieRetry.response) {
383:             response = cookieRetry.response;
384:             usedBrowserCookies = true;
385:             retrievalMethod = 'request-with-browser-cookies';
386:             contentType = String(response.headers['content-type'] || '').toLowerCase();
387:             finalUrl = response.request?.res?.responseUrl || parsedUrl.toString();
388:             assertPublicHttpUrl(finalUrl, 'Final URL');
389:             raw = typeof response.data === 'string'
390:                 ? response.data
391:                 : JSON.stringify(response.data, null, 2);
392:         }
393:     }
394: 
395:     const contentLength = Number(response.headers['content-length']);
396:     if (Number.isFinite(contentLength) && contentLength > MAX_DOWNLOAD_BYTES) {
397:         throw new Error(`Response body too large (${contentLength} bytes). Max allowed is ${MAX_DOWNLOAD_BYTES} bytes`);
398:     }
399: 
400:     let title = '';
401:     let extractedContent = '';
402:     let htmlExtraction: HtmlExtractionResult | undefined;
403:     let readabilityApplied = false;
404:     let readableHtml: string | undefined;
405:     let links: ExtractedLink[] | undefined;
406:     let byline: string | undefined;
407:     let excerpt: string | undefined;
408:     let siteName: string | undefined;
409: 
410:     const finalParsedUrl = new URL(finalUrl);
411: 
412:     // Keep raw markdown behavior for the resolved final path.
413:     if (isMarkdownPath(finalParsedUrl)) {
414:         extractedContent = normalizeText(raw);
415:     } else if (contentType.includes('text/html') || looksLikeHtml(raw)) {
416:         htmlExtraction = extractMainTextFromHtml(raw);
417:         title = htmlExtraction.title;
418:         extractedContent = htmlExtraction.text;
419:     } else if (isMarkdownContentType(contentType)) {
420:         extractedContent = normalizeText(raw);
421:     } else {
422:         extractedContent = normalizeText(raw);
423:     }
424: 
425:     if (shouldTryBrowserHtmlFallback(contentType, raw, htmlExtraction)) {
426:         const browserResult = await fetchHtmlViaBrowser(parsedUrl.toString());
427:         if (browserResult) {
428:             contentType = browserResult.contentType;
429:             finalUrl = browserResult.finalUrl;
430:             raw = browserResult.raw;
431:             retrievalMethod = 'browser-html';
432:             htmlExtraction = extractMainTextFromHtml(raw);
433:             title = htmlExtraction.title || browserResult.title;
434:             extractedContent = htmlExtraction.text;
435:         }
436:     }
437: 
438:     if (options.readability && (contentType.includes('text/html') || looksLikeHtml(raw))) {
439:         try {
440:             const article = await readabilityParser(raw, finalUrl);
441:             if (article?.content) {
442:                 const readableText = normalizeText(article.textContent || extractReadableTextFromHtml(article.content));
443:                 if (readableText) {
444:                     readabilityApplied = true;
445:                     readableHtml = article.content;
446:                     links = options.includeLinks ? extractReadableLinks(article.content, finalUrl) : undefined;
447:                     byline = article.byline?.trim() || undefined;
448:                     excerpt = article.excerpt?.trim() || undefined;
449:                     siteName = article.siteName?.trim() || undefined;
450:                     title = article.title?.trim() || title;
451:                     extractedContent = readableText;
452:                 }
453:             } else {
454:                 logReadabilityFallback('parser returned no article content');
455:             }
456:         } catch (error) {
457:             if (error instanceof ReadabilityUnavailableError) {
458:                 throw error;
459:             }
460: 
461:             logReadabilityFallback('falling back to existing extractor after parser error', error);
462:         }
463:     }
464: 
465:     if (!extractedContent) {
466:         throw new Error('No readable content was extracted from this URL');
467:     }
468: 
469:     const targetMaxChars = clampMaxChars(maxChars);
470:     const truncated = extractedContent.length > targetMaxChars;
471:     const content = truncated
472:         ? `${extractedContent.slice(0, targetMaxChars)}\n\n[...truncated ${extractedContent.length - targetMaxChars} characters]`
473:         : extractedContent;
474: 
475:     return {
476:         url: parsedUrl.toString(),
477:         finalUrl,
478:         contentType: contentType || 'unknown',
479:         title,
480:         retrievalMethod,
481:         truncated,
482:         content,
483:         ...(options.readability ? { readabilityApplied } : {}),
484:         ...(readableHtml ? { readableHtml } : {}),
485:         ...(links ? { links } : {}),
486:         ...(byline ? { byline } : {}),
487:         ...(excerpt ? { excerpt } : {}),
488:         ...(siteName ? { siteName } : {})
489:     };
490: }

