52:   if (shouldSuppressStartupLogs(argv)) {
53:     process.env.OPEN_WEBSEARCH_QUIET_STARTUP = 'true';
54:   }
55:   const { config } = await import('./config.js');
56:   const runtime = shouldCreateFullRuntimeForInvocation(argv)
57:     ? (await import('./runtime/createRuntime.js')).createOpenWebSearchRuntime()
58:     : ({
59:         config,
60:         services: {} as OpenWebSearchRuntime['services']
61:       } satisfies OpenWebSearchRuntime);
62:   const cliExitCode = await runCli(argv, runtime, {
63:     stdout: (text) => console.log(text),
64:     stderr: (text) => console.error(text)
65:   });
66: 
67:   if (cliExitCode !== null) {
68:     process.exitCode = cliExitCode;
69:     return;
70:   }
71: 
72:   // Enable STDIO mode if MODE is 'both' or 'stdio' or not specified
73:   if (process.env.MODE === undefined || process.env.MODE === 'both' || process.env.MODE === 'stdio') {
74:     console.error('🔌 Starting STDIO transport...');
75:     const server = createServer(runtime);
76:     const stdioTransport = new StdioServerTransport();
77:     await server.connect(stdioTransport).then(() => {
78:       console.error('✅ STDIO transport enabled');
79:     }).catch(error => {
80:       console.error('❌ Failed to initialize STDIO transport:', error);
81:     });
82:   }
83: 
84:   // Only set up HTTP server if enabled
85:   if (config.enableHttpServer) {
86:     console.error('🔌 Starting HTTP server...');
87:     // 创建 Express 应用
88:     const app = express();
89:     app.use(express.json());
90: 
91:     // 是否启用跨域
92:     if (config.enableCors) {
93:       app.use(cors({
94:         origin: config.corsOrigin || '*',
95:         methods: ['GET', 'POST', 'DELETE'],
96:       }));
97:       app.options('*', cors());
98:     }
99: 
100:     // Store transports for each session type
101:     const transports = {
102:       streamable: {} as Record<string, StreamableSession>,
103:       sse: {} as Record<string, SseSession>
104:     };
105: 
106:     // Handle POST requests for client-to-server communication
107:     app.post('/mcp', async (req, res) => {
108:       // Check for existing session ID
109:       const sessionId = req.headers['mcp-session-id'] as string | undefined;
110:       let transport: StreamableHTTPServerTransport;
111: 
112:       if (sessionId && transports.streamable[sessionId]) {
113:         // Reuse existing transport
114:         transport = transports.streamable[sessionId].transport;
115:       } else if (!sessionId && isInitializeRequest(req.body)) {
116:         // New initialization request
117:         const server = createServer(runtime);
118:         const session = {} as StreamableSession;
119: 
120:         transport = new StreamableHTTPServerTransport({
121:           sessionIdGenerator: () => randomUUID(),
122:           onsessioninitialized: (sessionId) => {
123:             // Store the transport by session ID
124:             transports.streamable[sessionId] = session;
125:           },
126:           // DNS rebinding protection is disabled by default for backwards compatibility. If you are running this server
127:           // locally, make sure to set:
128:           // enableDnsRebindingProtection: true,
129:           // allowedHosts: ['127.0.0.1'],
130:         });
131: 
132:         session.server = server;
133:         session.transport = transport;
134:         session.closed = false;
135: 
136:         // Clean up transport when closed
137:         transport.onclose = () => {
138:           if (transport.sessionId && transports.streamable[transport.sessionId] === session) {
139:             delete transports.streamable[transport.sessionId];
140:           }
141: 
142:           if (session.closed) {
143:             return;
144:           }
145: 
146:           session.closed = true;
147:           void server.close().catch(error => {
148:             console.error('❌ Failed to close streamable MCP server:', error);
149:           });
150:         };
151: 
152:         // Connect to the MCP server
153:         try {
154:           await server.connect(transport);
155:         } catch (error) {
156:           session.closed = true;
157:           void server.close().catch(closeError => {
158:             console.error('❌ Failed to close streamable MCP server after connect error:', closeError);
159:           });
160:           throw error;
161:         }
162:       } else {
163:         // Invalid request
164:         res.status(400).json({
165:           jsonrpc: '2.0',
166:           error: {
167:             code: -32000,
168:             message: 'Bad Request: No valid session ID provided',
169:           },
170:           id: null,
171:         });
172:         return;
173:       }
174: 
175:       // Handle the request
176:       await transport.handleRequest(req, res, req.body);
177:     });
178: 
179:     // Reusable handler for GET and DELETE requests
180:     const handleSessionRequest = async (req: express.Request, res: express.Response) => {
181:       const sessionId = req.headers['mcp-session-id'] as string | undefined;
182:       if (!sessionId || !transports.streamable[sessionId]) {
183:         res.status(400).send('Invalid or missing session ID');
184:         return;
185:       }
186: 
187:       const transport = transports.streamable[sessionId];
188:       await transport.transport.handleRequest(req, res);
189:     };
190: 
191:     // Handle GET requests for server-to-client notifications via SSE
192:     app.get('/mcp', handleSessionRequest);
193: 
194:     // Handle DELETE requests for session termination
195:     app.delete('/mcp', handleSessionRequest);
196: 
197:     // Legacy SSE endpoint for older clients
198:     app.get('/sse', async (req, res) => {
199:       // Create SSE transport for legacy clients
200:       const transport = new SSEServerTransport('/messages', res);
201:       const server = createServer(runtime);
202:       const session: SseSession = {
203:         server,
204:         transport,
205:         closed: false
206:       };
207: 
208:       transports.sse[transport.sessionId] = session;
209: 
210:       transport.onclose = () => {
211:         if (transports.sse[transport.sessionId] === session) {
212:           delete transports.sse[transport.sessionId];
213:         }
214: 
215:         if (session.closed) {
216:           return;
217:         }
218: 
219:         session.closed = true;
220:         void server.close().catch(error => {
221:           console.error('❌ Failed to close SSE MCP server:', error);
222:         });
223:       };
224: 
225:       try {
226:         await server.connect(transport);
227:       } catch (error) {
228:         delete transports.sse[transport.sessionId];
229:         session.closed = true;
230:         void server.close().catch(closeError => {
231:           console.error('❌ Failed to close SSE MCP server after connect error:', closeError);
232:         });
233:         throw error;
234:       }
235:     });
236: 
237:     // Legacy message endpoint for older clients
238:     app.post('/messages', async (req, res) => {
239:       const sessionId = req.query.sessionId as string;
240:       const session = transports.sse[sessionId];
241:       if (session) {
242:         await session.transport.handlePostMessage(req, res, req.body);
243:       } else {
244:         res.status(400).send('No transport found for sessionId');
245:       }
246:     });
247: 
248:     // Read the port number from the environment variable; use the default port 3000 if it is not set.
249:     const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;
250: 
251:     app.listen(PORT, '0.0.0.0', () => {
252:       console.error(`✅ HTTP server running on port ${PORT}`)
253:     });
254:   } else {
255:     console.error('ℹ️ HTTP server disabled, running in STDIO mode only')
256:   }
257: }
258: 
259: main().catch(console.error);

