1: import { config, getProxyUrl } from '../config.js';
2: import { openPlaywrightBrowser, loadPlaywrightClient } from './playwrightClient.js';
3: 
4: const COOKIE_CACHE_TTL_MS = 10 * 60 * 1000;
5: const COOKIE_WARMUP_DELAY_MS = 1200;
6: const COOKIE_CONTEXT_OPTIONS = {
7:     userAgent: 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/145.0.0.0 Safari/537.36',
8:     locale: 'zh-CN',
9:     viewport: { width: 1440, height: 960 }
10: };
11: const BOT_KEYWORDS = [
12:     'captcha',
13:     'verification',
14:     'verify you are human',
15:     'access denied',
16:     'blocked',
17:     'rate limit',
18:     'too many requests',
19:     'please enable javascript',
20:     'please verify',
21:     '请验证',
22:     '验证码',
23:     '人机验证',
24:     '安全验证'
25: ];
26: 
27: type CookieCacheEntry = {
28:     cookieHeader: string;
29:     expiresAt: number;
30: };
31: 
32: const cookieCache = new Map<string, CookieCacheEntry>();
33: 
34: function buildCookieCacheKey(url: URL): string {
35:     return [
36:         url.origin,
37:         getProxyUrl() || '-',
38:         config.playwrightPackage,
39:         config.playwrightModulePath || '-',
40:         config.playwrightExecutablePath || '-',
41:         config.playwrightWsEndpoint || '-',
42:         config.playwrightCdpEndpoint || '-'
43:     ].join('|');
44: }
45: 
46: function serializeCookieHeader(cookies: Array<{ name?: string; value?: string }>): string {
47:     return cookies
48:         .filter((cookie) => cookie.name && cookie.value !== undefined)
49:         .map((cookie) => `${cookie.name}=${cookie.value}`)
50:         .join('; ');
51: }
52: 
53: export function looksLikeBotChallengePage(html: string): boolean {
54:     const normalized = html.toLowerCase();
55:     return BOT_KEYWORDS.some((keyword) => normalized.includes(keyword));
56: }
57: 
58: async function createCookieCollectionPage(browser: any): Promise<{ page: any; close(): Promise<void> }> {
59:     if (typeof browser.newContext === 'function') {
60:         const context = await browser.newContext(COOKIE_CONTEXT_OPTIONS);
61:         const page = await context.newPage();
62:         return {
63:             page,
64:             close: async () => {
65:                 await context.close().catch(() => undefined);
66:             }
67:         };
68:     }
69: 
70:     if (typeof browser.contexts === 'function') {
71:         const contexts = browser.contexts();
72:         if (Array.isArray(contexts) && contexts.length > 0 && typeof contexts[0].newPage === 'function') {
73:             const page = await contexts[0].newPage();
74:             return {
75:                 page,
76:                 close: async () => {
77:                     await page.close().catch(() => undefined);
78:                 }
79:             };
80:         }
81:     }
82: 
83:     if (typeof browser.newPage === 'function') {
84:         const page = await browser.newPage();
85:         return {
86:             page,
87:             close: async () => {
88:                 await page.close().catch(() => undefined);
89:             }
90:         };
91:     }
92: 
93:     throw new Error('Connected Playwright browser does not support creating a page for cookie collection');
94: }
95: 
96: async function readCookiesFromPage(page: any, url: string): Promise<string> {
97:     if (typeof page.context === 'function') {
98:         const context = page.context();
99:         if (context && typeof context.cookies === 'function') {
100:             const cookies = await context.cookies([url]);
101:             return serializeCookieHeader(cookies);
102:         }
103:     }
104: 
105:     return '';
106: }
107: 
108: export async function getBrowserCookieHeader(urlInput: string, forceRefresh: boolean = false): Promise<string | undefined> {
109:     const url = new URL(urlInput);
110:     const cacheKey = buildCookieCacheKey(url);
111:     const cached = cookieCache.get(cacheKey);
112: 
113:     if (!forceRefresh && cached && cached.expiresAt > Date.now()) {
114:         return cached.cookieHeader;
115:     }
116: 
117:     const playwright = await loadPlaywrightClient({ silent: true });
118:     if (!playwright) {
119:         return undefined;
120:     }
121: 
122:     const session = await openPlaywrightBrowser(true);
123: 
124:     try {
125:         const { page, close } = await createCookieCollectionPage(session.browser);
126: 
127:         try {
128:             await page.goto(url.toString(), {
129:                 waitUntil: 'domcontentloaded',
130:                 timeout: Math.max(config.playwrightNavigationTimeoutMs, 15000)
131:             }).catch(() => undefined);
132:             if (typeof page.waitForTimeout === 'function') {
133:                 await page.waitForTimeout(COOKIE_WARMUP_DELAY_MS).catch(() => undefined);
134:             }
135: 
136:             const cookieHeader = await readCookiesFromPage(page, url.toString());
137:             if (!cookieHeader) {
138:                 return undefined;
139:             }
140: 
141:             cookieCache.set(cacheKey, {
142:                 cookieHeader,
143:                 expiresAt: Date.now() + COOKIE_CACHE_TTL_MS
144:             });
145: 
146:             return cookieHeader;
147:         } finally {
148:             await close();
149:         }
150:     } finally {
151:         await session.close();
152:     }
153: }
154: 
155: export async function fetchPageHtmlWithBrowser(urlInput: string): Promise<{ html: string; finalUrl: string; title: string }> {
156:     const playwright = await loadPlaywrightClient({ silent: true });
157:     if (!playwright) {
158:         throw new Error('Playwright client is not available for browser HTML fetch');
159:     }
160: 
161:     const session = await openPlaywrightBrowser(true);
162: 
163:     try {
164:         const { page, close } = await createCookieCollectionPage(session.browser);
165: 
166:         try {
167:             await page.goto(urlInput, {
168:                 waitUntil: 'domcontentloaded',
169:                 timeout: Math.max(config.playwrightNavigationTimeoutMs, 15000)
170:             });
171: 
172:             if (typeof page.waitForLoadState === 'function') {
173:                 await page.waitForLoadState('networkidle', {
174:                     timeout: Math.min(Math.max(config.playwrightNavigationTimeoutMs, 5000), 15000)
175:                 }).catch(() => undefined);
176:             }
177: 
178:             if (typeof page.waitForTimeout === 'function') {
179:                 await page.waitForTimeout(COOKIE_WARMUP_DELAY_MS).catch(() => undefined);
180:             }
181: 
182:             const html = typeof page.content === 'function' ? await page.content() : '';
183:             const finalUrl = typeof page.url === 'function' ? page.url() : urlInput;
184:             const title = typeof page.title === 'function' ? await page.title().catch(() => '') : '';
185: 
186:             return {
187:                 html: String(html || ''),
188:                 finalUrl: String(finalUrl || urlInput),
189:                 title: String(title || '')
190:             };
191:         } finally {
192:             await close();
193:         }
194:     } finally {
195:         await session.close();
196:     }
197: }

