1: import { createRequire } from 'module';
2: import path from 'path';
3: import { config, getProxyUrl } from '../config.js';
4: 
5: const PLAYWRIGHT_CONNECT_TIMEOUT_MS = Math.max(config.playwrightNavigationTimeoutMs, 30000);
6: const require = createRequire(import.meta.url);
7: 
8: export type PlaywrightChromium = {
9:     launch(options?: any): Promise<any>;
10:     connect(options: { wsEndpoint: string; timeout?: number; headers?: Record<string, string> }): Promise<any>;
11:     connectOverCDP(endpoint: string, options?: any): Promise<any>;
12: };
13: 
14: export type PlaywrightModule = {
15:     chromium: PlaywrightChromium;
16: };
17: 
18: export type PlaywrightBrowserSession = {
19:     browser: any;
20:     close(): Promise<void>;
21: };
22: 
23: type LoadPlaywrightClientOptions = {
24:     silent?: boolean;
25: };
26: 
27: let playwrightModulePromise: Promise<PlaywrightModule | null> | null = null;
28: let playwrightModuleSource: string | null = null;
29: let playwrightUnavailableMessage: string | null = null;
30: let hasEmittedPlaywrightUnavailableWarning = false;
31: 
32: function buildPlaywrightProxy(): { server: string; username?: string; password?: string } | undefined {
33:     const effectiveProxyUrl = getProxyUrl();
34:     if (!effectiveProxyUrl) {
35:         return undefined;
36:     }
37: 
38:     try {
39:         const proxyUrl = new URL(effectiveProxyUrl);
40:         return {
41:             server: `${proxyUrl.protocol}//${proxyUrl.hostname}${proxyUrl.port ? `:${proxyUrl.port}` : ''}`,
42:             username: proxyUrl.username ? decodeURIComponent(proxyUrl.username) : undefined,
43:             password: proxyUrl.password ? decodeURIComponent(proxyUrl.password) : undefined
44:         };
45:     } catch (error) {
46:         console.warn('Invalid proxy URL for Playwright, falling back without browser proxy:', error);
47:         return undefined;
48:     }
49: }
50: 
51: function normalizeLoadedPlaywrightModule(loaded: any): PlaywrightModule | null {
52:     if (loaded?.chromium) {
53:         return loaded as PlaywrightModule;
54:     }
55:     if (loaded?.default?.chromium) {
56:         return loaded.default as PlaywrightModule;
57:     }
58:     return null;
59: }
60: 
61: function getPlaywrightModuleCandidates(): Array<{ label: string; specifier: string }> {
62:     const candidates: Array<{ label: string; specifier: string }> = [];
63:     const seenSpecifiers = new Set<string>();
64: 
65:     const pushCandidate = (label: string, specifier: string) => {
66:         if (seenSpecifiers.has(specifier)) {
67:             return;
68:         }
69:         seenSpecifiers.add(specifier);
70:         candidates.push({ label, specifier });
71:     };
72: 
73:     if (config.playwrightModulePath) {
74:         const resolvedModulePath = path.isAbsolute(config.playwrightModulePath)
75:             ? config.playwrightModulePath
76:             : path.resolve(process.cwd(), config.playwrightModulePath);
77:         pushCandidate(`PLAYWRIGHT_MODULE_PATH (${resolvedModulePath})`, resolvedModulePath);
78:     }
79: 
80:     if (config.playwrightPackage === 'auto') {
81:         pushCandidate('playwright package', 'playwright');
82:         pushCandidate('playwright-core package', 'playwright-core');
83:     } else {
84:         pushCandidate(`${config.playwrightPackage} package`, config.playwrightPackage);
85:     }
86: 
87:     return candidates;
88: }
89: 
90: export function getPlaywrightModuleSource(): string | null {
91:     return playwrightModuleSource;
92: }
93: 
94: function emitPlaywrightUnavailableWarning(options?: LoadPlaywrightClientOptions): void {
95:     if (options?.silent || !playwrightUnavailableMessage || hasEmittedPlaywrightUnavailableWarning) {
96:         return;
97:     }
98: 
99:     hasEmittedPlaywrightUnavailableWarning = true;
100:     console.warn(playwrightUnavailableMessage);
101: }
102: 
103: export async function loadPlaywrightClient(options?: LoadPlaywrightClientOptions): Promise<PlaywrightModule | null> {
104:     if (!playwrightModulePromise) {
105:         playwrightModulePromise = (async () => {
106:             const attempts: string[] = [];
107: 
108:             for (const candidate of getPlaywrightModuleCandidates()) {
109:                 try {
110:                     const loaded = require(candidate.specifier);
111:                     const normalized = normalizeLoadedPlaywrightModule(loaded);
112:                     if (!normalized) {
113:                         attempts.push(`${candidate.label}: loaded module does not expose chromium`);
114:                         continue;
115:                     }
116: 
117:                     playwrightModuleSource = candidate.label;
118:                     playwrightUnavailableMessage = null;
119:                     hasEmittedPlaywrightUnavailableWarning = false;
120:                     console.error(`🧭 Playwright client resolved from ${candidate.label}`);
121:                     return normalized;
122:                 } catch (error) {
123:                     const message = error instanceof Error ? error.message : String(error);
124:                     attempts.push(`${candidate.label}: ${message}`);
125:                 }
126:             }
127: 
128:             playwrightUnavailableMessage = [
129:                 'Playwright client is unavailable, falling back to HTTP-only behavior.',
130:                 'Install `playwright` or `playwright-core`, or expose an existing client with PLAYWRIGHT_MODULE_PATH.',
131:                 `Attempts: ${attempts.join(' | ')}`
132:             ].join(' ');
133:             return null;
134:         })();
135:     }
136: 
137:     const playwright = await playwrightModulePromise;
138:     if (!playwright) {
139:         emitPlaywrightUnavailableWarning(options);
140:     }
141:     return playwright;
142: }
143: 
144: export async function openPlaywrightBrowser(headless: boolean, launchArgs: string[] = []): Promise<PlaywrightBrowserSession> {
145:     const playwright = await loadPlaywrightClient();
146:     if (!playwright) {
147:         throw new Error('Playwright client is not available. Install `playwright`/`playwright-core` manually or configure PLAYWRIGHT_MODULE_PATH.');
148:     }
149: 
150:     if (config.playwrightWsEndpoint) {
151:         const browser = await playwright.chromium.connect({
152:             wsEndpoint: config.playwrightWsEndpoint,
153:             timeout: PLAYWRIGHT_CONNECT_TIMEOUT_MS
154:         });
155:         return {
156:             browser,
157:             close: async () => {
158:                 await browser.close().catch(() => undefined);
159:             }
160:         };
161:     }
162: 
163:     if (config.playwrightCdpEndpoint) {
164:         const browser = await playwright.chromium.connectOverCDP(config.playwrightCdpEndpoint, {
165:             timeout: PLAYWRIGHT_CONNECT_TIMEOUT_MS
166:         });
167:         return {
168:             browser,
169:             close: async () => {
170:                 await browser.close().catch(() => undefined);
171:             }
172:         };
173:     }
174: 
