312: export async function fetchWebContent(
313:     url: string,
314:     maxChars: number = DEFAULT_MAX_CHARS,
315:     options: FetchWebContentOptions = {}
316: ): Promise<FetchWebContentResult> {
317:     const parsedUrl = new URL(url);
318:     await assertPublicHttpUrlResolved(parsedUrl, 'Request URL');
319: 
320:     const requestOptions = buildRequestOptions();
321: 
322:     // Pre-flight check to avoid downloading oversized payloads when Content-Length is present.
323:     try {
324:         const headResponse = await requestWithSafeRedirects('HEAD', parsedUrl.toString(), {
325:             ...requestOptions,
326:             responseType: 'json',
327:             validateStatus: (status: number) => status >= 200 && status < 400
328:         }, 'Request URL');
329:         const headLength = Number(headResponse.headers['content-length']);
330:         if (Number.isFinite(headLength) && headLength > MAX_DOWNLOAD_BYTES) {
331:             const tooLargeError = new Error(`Response body too large (${headLength} bytes). Max allowed is ${MAX_DOWNLOAD_BYTES} bytes`);
332:             (tooLargeError as any).code = 'ERR_RESPONSE_TOO_LARGE';
333:             throw tooLargeError;
334:         }
335:     } catch (error: any) {
336:         if (error?.code === 'ERR_RESPONSE_TOO_LARGE') {
337:             throw error;
338:         }
339:         const status = error?.response?.status;
340:         // Some servers don't support HEAD correctly; continue and rely on GET download limits.
341:         if (status !== undefined && ![400, 403, 404, 405, 406, 501].includes(status)) {
342:             throw error;
343:         }
344:     }
345: 
346:     let response: any;
347:     let usedBrowserCookies = false;
348:     let retrievalMethod: FetchWebContentResult['retrievalMethod'] = 'request';
349: 
350:     try {
351:         response = await requestWithSafeRedirects('GET', parsedUrl.toString(), requestOptions, 'Request URL');
352:     } catch (error: any) {
353:         const status = error?.response?.status;
354:         if (![401, 403, 429].includes(status)) {
355:             throw error;
356:         }
357: 
358:         const cookieRetry = await tryRequestWithBrowserCookies(parsedUrl.toString());
359:         if (cookieRetry.response) {
360:             response = cookieRetry.response;
361:             usedBrowserCookies = cookieRetry.usedBrowserCookies;
362:             retrievalMethod = 'request-with-browser-cookies';
363:         } else {
364:             response = {
365:                 headers: { 'content-type': 'text/html; charset=utf-8' },
366:                 data: '',
367:                 request: { res: { responseUrl: parsedUrl.toString() } }
368:             };
369:         }
370:     }
371: 
372:     let contentType = String(response.headers['content-type'] || '').toLowerCase();
373:     let finalUrl = response.request?.res?.responseUrl || parsedUrl.toString();
374:     assertPublicHttpUrl(finalUrl, 'Final URL');
375:     let raw = typeof response.data === 'string'
376:         ? response.data
377:         : JSON.stringify(response.data, null, 2);
378: 
379:     if (!usedBrowserCookies && looksLikeBotChallengePage(raw)) {
380:         const cookieRetry = await tryRequestWithBrowserCookies(parsedUrl.toString());
381:         if (cookieRetry.response) {
382:             response = cookieRetry.response;
383:             usedBrowserCookies = true;
384:             retrievalMethod = 'request-with-browser-cookies';
385:             contentType = String(response.headers['content-type'] || '').toLowerCase();
386:             finalUrl = response.request?.res?.responseUrl || parsedUrl.toString();
387:             assertPublicHttpUrl(finalUrl, 'Final URL');
388:             raw = typeof response.data === 'string'
389:                 ? response.data
390:                 : JSON.stringify(response.data, null, 2);
391:         }
392:     }
393: 
394:     const contentLength = Number(response.headers['content-length']);
395:     if (Number.isFinite(contentLength) && contentLength > MAX_DOWNLOAD_BYTES) {
396:         throw new Error(`Response body too large (${contentLength} bytes). Max allowed is ${MAX_DOWNLOAD_BYTES} bytes`);
397:     }
398: 
399:     let title = '';
400:     let extractedContent = '';
401:     let htmlExtraction: HtmlExtractionResult | undefined;
402:     let readabilityApplied = false;
403:     let readableHtml: string | undefined;
404:     let links: ExtractedLink[] | undefined;
405:     let byline: string | undefined;
406:     let excerpt: string | undefined;
407:     let siteName: string | undefined;
408: 
409:     const finalParsedUrl = new URL(finalUrl);
410: 
411:     // Keep raw markdown behavior for the resolved final path.
412:     if (isMarkdownPath(finalParsedUrl)) {
413:         extractedContent = normalizeText(raw);
414:     } else if (contentType.includes('text/html') || looksLikeHtml(raw)) {
415:         htmlExtraction = extractMainTextFromHtml(raw);
416:         title = htmlExtraction.title;
417:         extractedContent = htmlExtraction.text;
418:     } else if (isMarkdownContentType(contentType)) {
419:         extractedContent = normalizeText(raw);
420:     } else {
421:         extractedContent = normalizeText(raw);
422:     }
423: 
424:     if (shouldTryBrowserHtmlFallback(contentType, raw, htmlExtraction)) {
425:         const browserResult = await fetchHtmlViaBrowser(parsedUrl.toString());
426:         if (browserResult) {
427:             contentType = browserResult.contentType;
428:             finalUrl = browserResult.finalUrl;
429:             raw = browserResult.raw;
430:             retrievalMethod = 'browser-html';
431:             htmlExtraction = extractMainTextFromHtml(raw);
432:             title = htmlExtraction.title || browserResult.title;
433:             extractedContent = htmlExtraction.text;
434:         }
435:     }
436: 
437:     if (options.readability && (contentType.includes('text/html') || looksLikeHtml(raw))) {
438:         try {
439:             const article = await readabilityParser(raw, finalUrl);
440:             if (article?.content) {
441:                 const readableText = normalizeText(article.textContent || extractReadableTextFromHtml(article.content));
442:                 if (readableText) {
443:                     readabilityApplied = true;
444:                     readableHtml = article.content;
445:                     links = options.includeLinks ? extractReadableLinks(article.content, finalUrl) : undefined;
446:                     byline = article.byline?.trim() || undefined;
447:                     excerpt = article.excerpt?.trim() || undefined;
448:                     siteName = article.siteName?.trim() || undefined;
449:                     title = article.title?.trim() || title;
450:                     extractedContent = readableText;
451:                 }
452:             } else {
453:                 logReadabilityFallback('parser returned no article content');
454:             }
455:         } catch (error) {
456:             if (error instanceof ReadabilityUnavailableError) {
457:                 throw error;
458:             }
459: 
460:             logReadabilityFallback('falling back to existing extractor after parser error', error);
461:         }
462:     }
463: 
464:     if (!extractedContent) {
465:         throw new Error('No readable content was extracted from this URL');
466:     }
467: 
468:     const targetMaxChars = clampMaxChars(maxChars);
469:     const truncated = extractedContent.length > targetMaxChars;
470:     const content = truncated
471:         ? `${extractedContent.slice(0, targetMaxChars)}\n\n[...truncated ${extractedContent.length - targetMaxChars} characters]`
472:         : extractedContent;
473: 
474:     return {
475:         url: parsedUrl.toString(),
476:         finalUrl,
477:         contentType: contentType || 'unknown',
478:         title,
479:         retrievalMethod,
480:         truncated,
481:         content,
482:         ...(options.readability ? { readabilityApplied } : {}),
483:         ...(readableHtml ? { readableHtml } : {}),
484:         ...(links ? { links } : {}),
485:         ...(byline ? { byline } : {}),
486:         ...(excerpt ? { excerpt } : {}),
487:         ...(siteName ? { siteName } : {})
488:     };
489: }

