60: // Hostname-level TTL cache used by the subresource guard so a page loading
61: // N assets from one CDN costs one DNS lookup, not N. Bounded to keep memory
62: // capped; short TTL shrinks the DNS-rebinding window for subresources.
63: const SUBRESOURCE_CLASSIFICATION_TTL_MS = 60 * 1000;
64: const SUBRESOURCE_CLASSIFICATION_MAX_ENTRIES = 1024;
65: type SubresourceClassification = { allowed: boolean; expiresAt: number };
66: const subresourceClassificationCache = new Map<string, SubresourceClassification>();
67: 
68: function readSubresourceClassification(hostname: string): boolean | undefined {
69:     const entry = subresourceClassificationCache.get(hostname);
70:     if (!entry) {
71:         return undefined;
72:     }
73:     if (entry.expiresAt <= Date.now()) {
74:         subresourceClassificationCache.delete(hostname);
75:         return undefined;
76:     }
77:     return entry.allowed;
78: }
79: 
80: function writeSubresourceClassification(hostname: string, allowed: boolean): void {
81:     if (subresourceClassificationCache.size >= SUBRESOURCE_CLASSIFICATION_MAX_ENTRIES) {
82:         // Map preserves insertion order; drop the oldest.
83:         const oldestKey = subresourceClassificationCache.keys().next().value;
84:         if (oldestKey !== undefined) {
85:             subresourceClassificationCache.delete(oldestKey);
86:         }
87:     }
88:     subresourceClassificationCache.set(hostname, {
89:         allowed,
90:         expiresAt: Date.now() + SUBRESOURCE_CLASSIFICATION_TTL_MS
91:     });
92: }
