94: // Async variant for sub-resource requests. Uses the TTL cache so that common
95: // page-load patterns (dozens of assets from one CDN) don't trigger one DNS
96: // lookup per asset, while hostname-to-private resolutions are still caught.
97: export async function classifyBrowserSubresourceUrl(targetUrl: string): Promise<void> {
98:     const parsed = new URL(targetUrl);
99:     // Protocol + literal-IP private check first (sync, free).
100:     assertPublicHttpUrl(parsed, 'Browser subresource URL');
101: 
102:     // URL.hostname brackets IPv6 literals; any IP literal is already cleared above.
103:     const { hostname } = parsed;
104:     if (isIP(hostname) !== 0 || hostname.startsWith('[')) {
105:         return;
106:     }
107: 
108:     const cacheKey = hostname.toLowerCase();
109:     const cached = readSubresourceClassification(cacheKey);
110:     if (cached === true) {
111:         return;
112:     }
113:     if (cached === false) {
114:         throw new Error('Browser subresource URL points to a private or local network target, which is not allowed');
115:     }
116: 
117:     try {
118:         await assertPublicHttpUrlResolved(parsed, 'Browser subresource URL');
119:         writeSubresourceClassification(cacheKey, true);
120:     } catch (err) {
121:         writeSubresourceClassification(cacheKey, false);
122:         throw err;
123:     }
124: }
