134: // Intercepts every request the page makes (navigation + sub-resources) and
135: // aborts ones whose target is private/loopback at either the literal or
136: // DNS-resolved level. Navigation hits DNS fresh every time to keep the
137: // rebinding window tight; sub-resources go through a hostname TTL cache.
138: async function installNavigationGuard(page: any): Promise<void> {
139:     if (typeof page.route !== 'function') {
140:         return;
141:     }
142:     try {
143:         await page.route('**/*', async (route: any) => {
144:             const request = route.request();
145:             const targetUrl = request.url();
146:             try {
147:                 if (request.isNavigationRequest()) {
148:                     await assertPublicHttpUrlResolved(targetUrl, 'Browser navigation URL');
149:                 } else {
150:                     await classifyBrowserSubresourceUrl(targetUrl);
151:                 }
152:                 await route.continue();
153:             } catch {
154:                 await route.abort().catch(() => undefined);
155:             }
156:         });
157:     } catch {
158:         // Some connected browsers (e.g., certain CDP setups) may not support route
159:         // interception. Pre-navigation validation still gates the initial URL.
160:     }
161: }
