213: export async function getBrowserCookieHeader(urlInput: string, forceRefresh: boolean = false): Promise<string | undefined> {
214:     const url = new URL(urlInput);
215:     await assertPublicHttpUrlResolved(url, 'Browser cookie URL');
216:     const cacheKey = buildCookieCacheKey(url);
217:     const cached = cookieCache.get(cacheKey);
218: 
219:     if (!forceRefresh && cached && cached.expiresAt > Date.now()) {
220:         return cached.cookieHeader;
221:     }
222: 
223:     const playwright = await loadPlaywrightClient({ silent: true });
224:     if (!playwright) {
225:         return undefined;
226:     }
227: 
228:     const session = await openPlaywrightBrowser(true);
229: 
230:     try {
231:         const { page, close } = await createCookieCollectionPage(session.browser);
232: 
233:         try {
234:             await installNavigationGuard(page);
235:             await page.goto(url.toString(), {
236:                 waitUntil: 'domcontentloaded',
237:                 timeout: Math.max(config.playwrightNavigationTimeoutMs, 15000)
238:             }).catch(() => undefined);
239:             if (typeof page.waitForTimeout === 'function') {
240:                 await page.waitForTimeout(COOKIE_WARMUP_DELAY_MS).catch(() => undefined);
241:             }
242: 
243:             const cookieHeader = await readCookiesFromPage(page, url.toString());
244:             if (!cookieHeader) {
245:                 return undefined;
246:             }
247: 
248:             cookieCache.set(cacheKey, {
249:                 cookieHeader,
250:                 expiresAt: Date.now() + COOKIE_CACHE_TTL_MS
251:             });
252: 
253:             return cookieHeader;
254:         } finally {
255:             await close();
256:         }
257:     } finally {
258:         await session.close();
259:     }
260: }
