262: export async function fetchPageHtmlWithBrowser(urlInput: string): Promise<{ html: string; finalUrl: string; title: string }> {
263:     await assertPublicHttpUrlResolved(urlInput, 'Browser fetch URL');
264: 
265:     const playwright = await loadPlaywrightClient({ silent: true });
