275:         try {
276:             await installNavigationGuard(page);
277:             await page.goto(urlInput, {
278:                 waitUntil: 'domcontentloaded',
279:                 timeout: Math.max(config.playwrightNavigationTimeoutMs, 15000)
280:             });
281: 
282:             if (typeof page.waitForLoadState === 'function') {
283:                 await page.waitForLoadState('networkidle', {
284:                     timeout: Math.min(Math.max(config.playwrightNavigationTimeoutMs, 5000), 15000)
285:                 }).catch(() => undefined);
286:             }
287: 
288:             if (typeof page.waitForTimeout === 'function') {
289:                 await page.waitForTimeout(COOKIE_WARMUP_DELAY_MS).catch(() => undefined);
290:             }
291: 
292:             const html = typeof page.content === 'function' ? await page.content() : '';
293:             const finalUrl = typeof page.url === 'function' ? page.url() : urlInput;
294:             const title = typeof page.title === 'function' ? await page.title().catch(() => '') : '';
295: 
296:             return {
297:                 html: String(html || ''),
298:                 finalUrl: String(finalUrl || urlInput),
299:                 title: String(title || '')
300:             };
301:         } finally {
302:             await close();
303:         }
304:     } finally {
305:         await session.close();
306:     }
